class ConfigManager:
    def __init__(self, config_file='config.json'):
        self.config_file = config_file
        self.config = self._load_config()
        self.defaults = {
            'debug': False,
            'max_connections': 100,
            'timeout': 30,
            'log_level': 'INFO'
        }

    def _load_config(self):
        try:
            with open(self.config_file, 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            print(f"Config file {self.config_file} not found, using defaults")
            return {}
        except json.JSONDecodeError as e:
            print(f"Invalid JSON in config file: {e}")
            return {}

    def get(self, key, default=None):
        # check config first, then defaults, then provided default
        return self.config.get(key, self.defaults.get(key, default))

    def set(self, key, value):
        # basic validation for known keys
        if key == 'max_connections' and not isinstance(value, int):
            raise ValueError("max_connections must be an integer")
        if key == 'timeout' and (not isinstance(value, (int, float)) or value <= 0):
            raise ValueError("timeout must be a positive number")

        self.config[key] = value
        self._save_config()

    def _save_config(self):
        try:
            with open(self.config_file, 'w') as f:
                json.dump(self.config, f, indent=2)
        except Exception as e:
            print(f"Couldn't save config: {e}")

def start_watching(self):
        self.watching = True
        self.watch_thread = threading.Thread(target=self._watch_loop)
        self.watch_thread.daemon = True
        self.watch_thread.start()

    def stop_watching(self):
        self.watching = False
        if self.watch_thread:
            self.watch_thread.join()

def _create_handler(self):
        routes = self.routes
        middleware = self.middleware

        class RequestHandler(http.server.BaseHTTPRequestHandler):
            def do_GET(self):
                self._handle_request('GET')

            def do_POST(self):
                self._handle_request('POST')

            def _handle_request(self, method):
                # apply middleware
                for mw in middleware:
                    if not mw(self):
                        return

                route_key = f"{method} {self.path}"

                if route_key in routes:
                    try:
                        # simple request context
                        request_data = {
                            'method': method,
                            'path': self.path,
                            'headers': dict(self.headers),
                        }

                        if method == 'POST':
                            content_length = int(self.headers.get('Content-Length', 0))
                            request_data['body'] = self.rfile.read(content_length).decode('utf-8')

                        response = routes[route_key](request_data)

                        self.send_response(200)
                        self.send_header('Content-type', 'application/json')
                        self.end_headers()

                        if isinstance(response, dict):
                            self.wfile.write(json.dumps(response).encode())
                        else:
                            self.wfile.write(str(response).encode())

                    except Exception as e:
                        self.send_error(500, f"Internal error: {e}")
                else:
                    self.send_error(404, "Not found")

        return RequestHandler

def search_for_api_calls(
    file_path: str, api_pattern: list[Pattern[str]]
) -> dict[str, list[str]] | None:
    """
    Searches for API calls in a given file and returns a list of the API calls found.

    Parameters
    ----------
    file_path: str
        The path to the file to be searched.

    Returns
    -------
    dict
        A dict with the file name as the key and the API calls found in the file.
    """
    file_name = os.path.basename(file_path)

    api_calls: dict[str, list[str]] = {file_name: []}
    with open(file_path, "r", encoding="utf-8") as file:
        try:
            for line in file:
                for pattern in api_pattern:
                    if results := re.findall(pattern, line):
                        api_calls[file_name].extend(results)

        except UnicodeDecodeError:
            print(f"Skipping non-UTF-8 encoded line in {file_path}")

    return None if len(api_calls[file_name]) == 0 else api_calls

