  constructor(apiBaseUrl) {
    this.apiBaseUrl = apiBaseUrl;
    this.tokenKey = 'auth_token';
  }

  /**
   * Authenticates user and stores JWT token
   * @param {string} email - User email
   * @param {string} password - User password
   * @returns {Promise<Object>} Authentication response
   */
  async login(email, password) {
    try {
      const response = await fetch(`${this.apiBaseUrl}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });

      if (!response.ok) throw new Error('Authentication failed');

      const data = await response.json();
      localStorage.setItem(this.tokenKey, data.token);
      return data;
    } catch (error) {
      console.error('Login error:', error);
      throw error;
    }
  }

  // Get stored token with expiration check
  getToken() {
    const token = localStorage.getItem(this.tokenKey);
    if (!token) return null;

    try {
      const payload = JSON.parse(atob(token.split('.')[1]));
      return payload.exp > Date.now() / 1000 ? token : null;
    } catch {
      return null; // Invalid token format
    }
  }
}

import React, { useState, useEffect, useCallback, useMemo } from 'react';

const ShoppingCart = ({ userId, onCheckout }) => {
  const [cartItems, setCartItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Memoized total calculation
  const cartTotal = useMemo(() => 
    cartItems.reduce((sum, item) => sum + (item.price * item.quantity), 0),
    [cartItems]
  );

  const updateQuantity = useCallback((productId, newQuantity) => {
    if (newQuantity <= 0) {
      setCartItems(prev => prev.filter(item => item.id !== productId));
    } else {
      setCartItems(prev => prev.map(item => 
        item.id === productId 
          ? { ...item, quantity: newQuantity }
          : item
      ));
    }
  }, []);

  useEffect(() => {
    const loadCart = async () => {
      try {
        setLoading(true);
        const response = await fetch(`/api/cart/${userId}`);
        const data = await response.json();
        setCartItems(data.items || []);
      } catch (err) {
        setError('Failed to load cart');
      } finally {
        setLoading(false);
      }
    };

    if (userId) loadCart();
  }, [userId]);

  if (loading) return <div className="loading-spinner">Loading cart...</div>;
  if (error) return <div className="error-message">{error}</div>;

  return (
    <div className="shopping-cart">
      {cartItems.map(item => (
        <div key={item.id} className="cart-item">
          <span>{item.name}</span>
          <input 
            type="number" 
            value={item.quantity}
            onChange={e => updateQuantity(item.id, parseInt(e.target.value))}
            min="0"
          />
          <span>${(item.price * item.quantity).toFixed(2)}</span>
        </div>
      ))}
      <div className="cart-total">Total: ${cartTotal.toFixed(2)}</div>
      <button onClick={() => onCheckout(cartItems, cartTotal)}>
        Checkout
      </button>
    </div>
  );
};

const processUserData = (users) => {
  return users
    .filter(user => user.active && user.verified) // Only active, verified users
    .map(user => ({
      ...user,
      fullName: `${user.firstName} ${user.lastName}`,
      accountAge: Math.floor((Date.now() - new Date(user.createdAt)) / (1000 * 60 * 60 * 24))
    }))
    .sort((a, b) => b.accountAge - a.accountAge) // Sort by account age descending
    .reduce((acc, user) => {
      const tier = user.accountAge > 365 ? 'premium' : 'standard';
      acc[tier] = acc[tier] || [];
      acc[tier].push(user);
      return acc;
    }, {});
};

