      this.states[previousState].onExit(action, payload);
    }

    // Update state
    this.currentState = nextState;

    // Execute entry action for new state
    if (this.states[nextState].onEntry) {
      this.states[nextState].onEntry(action, payload);
    }

    // Notify listeners
    this.emit('stateChanged', {
      from: previousState,
      to: nextState,
      action,
      payload
    });

