        let shiftIndex = 0;
        while (shiftIndex < shifts.length) {
            const shift = shifts[shiftIndex];
            totalUnits += shift.unitsProduced;
            totalHours += shift.hoursWorked;
            downtimeHours += shift.downtime || 0;

            const hourlyRate = shift.unitsProduced / shift.hoursWorked;
            hourlyRates.push(hourlyRate);
