        const avgRate = hourlyRates.reduce((sum, rate) => sum + rate, 0) / hourlyRates.length;
        let variance = 0;

        for (let rate of hourlyRates) {
            variance += Math.pow(rate - avgRate, 2);
        }

        const stdDev = Math.sqrt(variance / hourlyRates.length);
        const consistency = stdDev === 0 ? 100 : Math.max(0, 100 - (stdDev / avgRate) * 100);

