selectOptimalServer() {
        let bestServer = null;
        let bestScore = Infinity;

        for (let i = 0; i < this.servers.length; i++) {
            const server = this.servers[i];

            if (!server.healthy) continue;

            // Calculate server score (lower is better)
            const loadWeight = 0.4;
            const responseWeight = 0.3;
            const capacityWeight = 0.3;

            const loadScore = server.currentLoad / server.maxCapacity;
            const avgResponseTime = server.responseTimeHistory.length > 0 
                ? server.responseTimeHistory.reduce((a, b) => a + b) / server.responseTimeHistory.length 
                : 50;
            const responseScore = avgResponseTime / 100; // normalize to 0-1 scale
            const capacityScore = 1 - (server.maxCapacity / 100); // prefer higher capacity

            const totalScore = (loadScore * loadWeight) + (responseScore * responseWeight) + (capacityScore * capacityWeight);

            if (totalScore < bestScore) {
                bestScore = totalScore;
                bestServer = server;
            }
        }

        return bestServer;

const taskDurations = new Map(tasks.map(task => [
            task.id, 
            Math.ceil((task.estimatedHours || 8) / 8) // Convert to days
        ]));

        const criticalTasks = [];
        let currentTasks = tasks.filter(task => task.dependencies.length === 0);

        while (currentTasks.length > 0) {
            const longestTask = currentTasks.reduce((longest, current) => 
                taskDurations.get(current.id) > taskDurations.get(longest.id) ? current : longest
            );

            criticalTasks.push(longestTask.id);

            currentTasks = tasks.filter(task => 
                task.dependencies.some(dep => dep.id === longestTask.id)
            );

