public class DatabaseConnectionConfig {

    private final String host;
    private final int port;
    private final String database;
    private final String username;
    private final String password;
    private final int maxPoolSize;
    private final int minPoolSize;
    private final Duration connectionTimeout;
    private final Duration idleTimeout;
    private final boolean enableSSL;
    private final Map<String, String> additionalProperties;

    private DatabaseConnectionConfig(Builder builder) {
        this.host = builder.host;
        this.port = builder.port;
        this.database = builder.database;
        this.username = builder.username;
        this.password = builder.password;
        this.maxPoolSize = builder.maxPoolSize;
        this.minPoolSize = builder.minPoolSize;
        this.connectionTimeout = builder.connectionTimeout;
        this.idleTimeout = builder.idleTimeout;
        this.enableSSL = builder.enableSSL;
        this.additionalProperties = Map.copyOf(builder.additionalProperties);
    }

    public static class Builder {
        // Required parameters
        private String host;
        private String database;
        private String username;
        private String password;

        // Optional parameters with defaults
        private int port = 5432;
        private int maxPoolSize = 20;
        private int minPoolSize = 5;
        private Duration connectionTimeout = Duration.ofSeconds(30);
        private Duration idleTimeout = Duration.ofMinutes(10);
        private boolean enableSSL = true;
        private Map<String, String> additionalProperties = new HashMap<>();

        public Builder(String host, String database, String username, String password) {
            this.host = Objects.requireNonNull(host, "Host cannot be null");
            this.database = Objects.requireNonNull(database, "Database cannot be null");
            this.username = Objects.requireNonNull(username, "Username cannot be null");
            this.password = Objects.requireNonNull(password, "Password cannot be null");
        }

        public Builder port(int port) {
            if (port < 1 || port > 65535) {
                throw new IllegalArgumentException("Port must be between 1 and 65535");
            }
            this.port = port;
            return this;
        }

        public Builder maxPoolSize(int maxPoolSize) {
            if (maxPoolSize < 1) {
                throw new IllegalArgumentException("Max pool size must be positive");
            }
            this.maxPoolSize = maxPoolSize;
            return this;
        }

        public Builder minPoolSize(int minPoolSize) {
            if (minPoolSize < 0) {
                throw new IllegalArgumentException("Min pool size cannot be negative");
            }
            this.minPoolSize = minPoolSize;
            return this;
        }

        public Builder connectionTimeout(Duration timeout) {
            this.connectionTimeout = Objects.requireNonNull(timeout, "Connection timeout cannot be null");
            return this;
        }

        public Builder idleTimeout(Duration timeout) {
            this.idleTimeout = Objects.requireNonNull(timeout, "Idle timeout cannot be null");
            return this;
        }

        public Builder enableSSL(boolean enableSSL) {
            this.enableSSL = enableSSL;
            return this;
        }

        public Builder addProperty(String key, String value) {
            this.additionalProperties.put(
                Objects.requireNonNull(key, "Property key cannot be null"),
                Objects.requireNonNull(value, "Property value cannot be null")
            );
            return this;
        }

        public DatabaseConnectionConfig build() {
            validate();
            return new DatabaseConnectionConfig(this);
        }

        private void validate() {
            if (minPoolSize > maxPoolSize) {
                throw new IllegalStateException("Min pool size cannot be greater than max pool size");
            }

            if (connectionTimeout.isNegative() || connectionTimeout.isZero()) {
                throw new IllegalArgumentException("Connection timeout must be positive");
            }
        }
    }

    // Getters...
    public String getHost() { return host; }
    public int getPort() { return port; }
    public String getDatabase() { return database; }
    // ... other getters

    @Override
    public String toString() {
        return String.format("DatabaseConfig{host='%s', port=%d, database='%s', poolSize=%d-%d}", 
                           host, port, database, minPoolSize, maxPoolSize);
    }
}

public class SalesAnalyticsProcessor {

    // Compact, functional approach to data analysis
    public SalesReport generateMonthlySalesReport(List<Transaction> transactions, YearMonth month) {
        Map<String, BigDecimal> categoryTotals = transactions.stream()
            .filter(t -> YearMonth.from(t.getDate()).equals(month))
            .filter(t -> t.getStatus() == TransactionStatus.COMPLETED)
            .collect(groupingBy(
                Transaction::getCategory,
                mapping(Transaction::getAmount, reducing(BigDecimal.ZERO, BigDecimal::add))
            ));

        // Find top performing products
        List<ProductSummary> topProducts = transactions.stream()
            .filter(t -> YearMonth.from(t.getDate()).equals(month))
            .flatMap(t -> t.getItems().stream())
            .collect(groupingBy(
                Item::getProductId,
                collectingAndThen(
                    toList(),
                    items -> new ProductSummary(
                        items.get(0).getProductName(),
                        items.size(),
                        items.stream().mapToDouble(Item::getPrice).sum()
                    )
                )
            ))
            .values()
            .stream()
            .sorted(comparing(ProductSummary::getTotalRevenue).reversed())
            .limit(10)
            .collect(toList());

        // Calculate trends compared to previous month
        YearMonth previousMonth = month.minusMonths(1);
        Optional<BigDecimal> currentTotal = categoryTotals.values().stream()
            .reduce(BigDecimal::add);

        Optional<BigDecimal> previousTotal = transactions.stream()
            .filter(t -> YearMonth.from(t.getDate()).equals(previousMonth))
            .map(Transaction::getAmount)
            .reduce(BigDecimal::add);

        double growthRate = calculateGrowthRate(previousTotal, currentTotal);

        return SalesReport.builder()
            .month(month)
            .categoryTotals(categoryTotals)
            .topProducts(topProducts)
            .totalRevenue(currentTotal.orElse(BigDecimal.ZERO))
            .growthRate(growthRate)
            .build();
    }

    private double calculateGrowthRate(Optional<BigDecimal> previous, Optional<BigDecimal> current) {
        return previous.filter(p -> p.compareTo(BigDecimal.ZERO) > 0)
            .flatMap(p -> current.map(c -> c.subtract(p).divide(p, 4, RoundingMode.HALF_UP).doubleValue()))
            .orElse(0.0);
    }
}

**
 * Service responsible for processing customer orders in the e-commerce platform.
 * Handles validation, inventory checks, payment processing, and order fulfillment.
 * 
 * @author Development Team
 * @version 2.1.0
 * @since 1.0.0
 */
@Service
@Transactional
public class OrderProcessingService {

    private static final Logger logger = LoggerFactory.getLogger(OrderProcessingService.class);
    private static final int MAX_RETRY_ATTEMPTS = 3;

    @Autowired
    private InventoryService inventoryService;

    @Autowired
    private PaymentGateway paymentGateway;

    @Autowired
    private NotificationService notificationService;

    /**
     * Processes a customer order through the complete workflow.
     * 
     * @param orderRequest the order details from the customer
     * @return OrderResult containing success status and order details
     * @throws OrderProcessingException if processing fails after retries
     */
    public OrderResult processOrder(OrderRequest orderRequest) throws OrderProcessingException {
        logger.info("Processing order for customer: {}", orderRequest.getCustomerId());

        try {
            // Step 1: Validate order data
            validateOrderRequest(orderRequest);

            // Step 2: Check inventory availability
            if (!inventoryService.checkAvailability(orderRequest.getItems())) {
                throw new InsufficientInventoryException("Items not available in requested quantities");
            }

            // Step 3: Reserve inventory
            List<InventoryReservation> reservations = inventoryService.reserveItems(orderRequest.getItems());

            try {
                // Step 4: Process payment with retry logic
                PaymentResult paymentResult = processPaymentWithRetry(orderRequest.getPaymentDetails());

                // Step 5: Create order record
                Order order = createOrderRecord(orderRequest, paymentResult, reservations);

                // Step 6: Send confirmation
                notificationService.sendOrderConfirmation(order);

                logger.info("Order {} processed successfully for customer {}", 
                           order.getOrderId(), orderRequest.getCustomerId());

                return new OrderResult(true, order, "Order processed successfully");

            } catch (PaymentException e) {
                // Release reserved inventory on payment failure
                inventoryService.releaseReservations(reservations);
                throw new OrderProcessingException("Payment processing failed: " + e.getMessage(), e);
            }

        } catch (Exception e) {
            logger.error("Order processing failed for customer {}: {}", 
                        orderRequest.getCustomerId(), e.getMessage(), e);
            throw new OrderProcessingException("Order processing failed", e);
        }
    }

    private PaymentResult processPaymentWithRetry(PaymentDetails paymentDetails) throws PaymentException {
        int attempts = 0;
        PaymentException lastException = null;

        while (attempts < MAX_RETRY_ATTEMPTS) {
            try {
                return paymentGateway.processPayment(paymentDetails);
            } catch (PaymentException e) {
                attempts++;
                lastException = e;
                logger.warn("Payment attempt {} failed: {}", attempts, e.getMessage());

                if (attempts < MAX_RETRY_ATTEMPTS) {
                    try {
                        Thread.sleep(1000 * attempts); // Exponential backoff
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        throw new PaymentException("Payment processing interrupted", ie);
                    }
                }
            }
        }

        throw new PaymentException("Payment failed after " + MAX_RETRY_ATTEMPTS + " attempts", lastException);
    }
}

public Page<T> findAll(Pageable pageable) {
        CriteriaBuilder cb = entityManager.getCriteriaBuilder();

        // Count query for total elements
        CriteriaQuery<Long> countQuery = cb.createQuery(Long.class);
        Root<T> countRoot = countQuery.from(entityClass);
        countQuery.select(cb.count(countRoot));
        Long total = entityManager.createQuery(countQuery).getSingleResult();

        // Data query with pagination
        CriteriaQuery<T> dataQuery = cb.createQuery(entityClass);
        Root<T> dataRoot = dataQuery.from(entityClass);
        dataQuery.select(dataRoot);

        // Apply sorting if specified
        if (pageable.getSort().isSorted()) {
            List<Order> orders = new ArrayList<>();
            for (Sort.Order order : pageable.getSort()) {
                if (order.isAscending()) {
                    orders.add(cb.asc(dataRoot.get(order.getProperty())));
                } else {
                    orders.add(cb.desc(dataRoot.get(order.getProperty())));
                }
            }
            dataQuery.orderBy(orders);
        }

        TypedQuery<T> typedQuery = entityManager.createQuery(dataQuery);
        typedQuery.setFirstResult((int) pageable.getOffset());
        typedQuery.setMaxResults(pageable.getPageSize());

        List<T> content = typedQuery.getResultList();
        return new PageImpl<>(content, pageable, total);
    }

@Transactional
   public T save(T entity) {
       if (isNew(entity)) {
           entityManager.persist(entity);
           return entity;
       } else {
           return entityManager.merge(entity);
       }
   }

   @Transactional
   public void deleteById(ID id) {
       findById(id).ifPresent(entity -> {
           if (entityManager.contains(entity)) {
               entityManager.remove(entity);
           } else {
               entityManager.remove(entityManager.merge(entity));
           }
       });
   }

   @Transactional
   public void delete(T entity) {
       if (entityManager.contains(entity)) {
           entityManager.remove(entity);
       } else {
           entityManager.remove(entityManager.merge(entity));
       }
   }

protected boolean isNew(T entity) {
        // Simple check - in real implementation you'd check the ID or version
        try {
            Field idField = entityClass.getDeclaredField("id");
            idField.setAccessible(true);
            return idField.get(entity) == null;
        } catch (Exception e) {
            // Fallback to checking if entity is managed
            return !entityManager.contains(entity);
        }
    }

    /**
     * Execute a named query with parameters
     */
    protected List<T> executeNamedQuery(String queryName, Map<String, Object> parameters) {
        TypedQuery<T> query = entityManager.createNamedQuery(queryName, entityClass);
        parameters.forEach(query::setParameter);
        return query.getResultList();
    }

