public LRUCache(int maxSize) {
       if (maxSize <= 0) {
           throw new IllegalArgumentException("Cache size must be positive");
       }

       this.maxSize = maxSize;
       this.cache = new HashMap<>(maxSize);

       // Initialize dummy head and tail nodes
       this.head = new Node<>(null, null);
       this.tail = new Node<>(null, null);
       head.next = tail;
       tail.prev = head;
   }

public Optional<V> get(K key) {
        readLock.lock();
        try {
            Node<K, V> node = cache.get(key);
            if (node == null) {
                misses++;
                return Optional.empty();
            }

            hits++;
            // Move to front (most recently used)
            moveToHead(node);
            return Optional.of(node.value);

        } finally {
            readLock.unlock();
        }
    }

package net.kenyang.algorithm;


public class LinkedListCycle {
    class ListNode {
        int val;
        ListNode next;

        ListNode(int x) {
            val = x;
            next = null;
        }
    }


    public boolean hasCycle(ListNode head) {

        ListNode slowNode = head;
        ListNode fastNode = head;
        if (head !=null && head.next != null) {
            fastNode = head.next;
        } else {
            return false;
        }

        while (slowNode !=null && fastNode!=null){
            if (slowNode.val == fastNode.val ) return true;

            slowNode = slowNode.next;
            fastNode = fastNode.next;
            if (fastNode!=null){
                fastNode = fastNode.next;
            }
        }

        return false;
    }
}

package net.kenyang.algorithm;

/**
 * Given a binary tree, find its maximum depth.
 * The maximum depth is the number of nodes along the longest path from the root node down to the farthest leaf node.
 * @author Ken Yang
 *
 */
public class MaximumDepthOfBinaryTree {
    public class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int x) {
            val = x;
        }
    }

    public int maxDepth(TreeNode root) {

        if (root == null) {
            return 0;
        }

        int iRightDepth = maxDepth(root.right);
        int iLefttDepth = maxDepth(root.left);
        return (iRightDepth > iLefttDepth) ? iRightDepth + 1 : iLefttDepth + 1;
    }
}

package net.kenyang.algorithm;

/**
 * Reverse digits of an integer.
 * 
 * Example1: x = 123, return 321
 * Example2: x = -123, return -321
 * @author Ken Yang
 *
 */
public class ReverseInteger {
    public int reverse(int x){
        int newValue = 0;
        while (x!=0) {
            int mod = x % 10;
            newValue = newValue*10 + mod;
            x /=10;
        }
        return newValue;
    }
}

