/**
 * Given two binary trees, write a function to check if they are equal or not.
 * Two binary trees are considered equal if they are structurally identical and the nodes have the same value.
 * @author Ken Yang
 *
 */
public class SameTree {
    public class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;
        TreeNode(int x) {
            val = x;
        }
    }

    public boolean isSameTree(TreeNode p, TreeNode q) {
        if (p == null && q == null) {
            return true;
        }

        if ((p != null && q == null) 
                || (p == null && q != null)
                || (p.val != q.val)) {
            return false;
        }

        return isSameTree(p.left, q.left) && isSameTree(p.right, q.right);

    }
}

public class SingleNumber {
    public int singleNumber(int[] A) {
        int num = 0;
        for (int i = 0; i < A.length; i++) {
            num ^= A[i];
        }
        return num;
    }
}

public class SymmetricTree {

    public class TreeNode {
        int val;
        TreeNode left;
        TreeNode right;

        TreeNode(int x) {
            val = x;
        }
    }

    public boolean isSymmetric(TreeNode root) {
        if (root == null) {
            return true;
        }

        return isSymmetric(root.left, root.right);
    }

    public boolean isSymmetric(TreeNode leftNode, TreeNode rightNode) {
        if (rightNode == null && leftNode == null)
            return true;
        if (rightNode == null)
            return false;
        if (leftNode == null)
            return false;


        return leftNode.val == rightNode.val
                && isSymmetric(leftNode.left, rightNode.right)
                && isSymmetric(leftNode.right, rightNode.left);

    }
}

public int numTrees(int n) {

        if (n<2) {
            return 1;
        }
        int ans = 0;
        for(int i = 0; i < n; i++) {
            ans += numTrees(i) * numTrees(n-i-1);
        }
        return ans;

    }

/**
 * Say you have an array for which the i element is the price of a given stock on day i.
 * If you were only permitted to complete at most one transaction (ie, buy one and sell one share of the stock), design an algorithm to find the maximum profit.
 * @author Ken Yang
 *
 */
public class BestTimeToBuyAndSellStock {
    public int maxProfit(int[] prices) {
        int size = prices.length;

        if (size<=1){
            return 0;
        }

        int min = prices[0];
        int max = prices[1] - min;
        for (int i = 2; i < size; i++) {

            if (min > prices[i-1]) {
                min = prices[i-1];
            }

            if (max < (prices[i]-min)) {
                max = prices[i]-min;
            }

        }


        return (max<0) ? 0 : max;
    }
}

public void set(int key, int value) {

        Node current = map.get(key);
        if (current != null) {
            current.value = value;
            if (iFirstKey == key) {
                iFirstKey = current.nextKey;
                updateToNewestNode(current, key);
            } else if (key != iLastKey) {
                reconnectNode(current);
                updateToNewestNode(current, key);
            }
        } else {
            current = new Node();
            current.value = value;
            current.preKey = iLastKey;

            if (iCurrentSize >= iCapacity) {
                int newFirstKey = map.get(iFirstKey).nextKey;
                map.remove(iFirstKey);
                iFirstKey = newFirstKey;
            } else {
                iCurrentSize++;
            }

            if (iLastKey != -1 && iCurrentSize != 1) {
                map.get(iLastKey).nextKey = key;
            }

            iLastKey = key;
        }
        map.put(key, current);

        if (iFirstKey == -1) {
            iFirstKey = key;
        }

    }

