public int countPermutations(int[] complexity) {
        final int mod = (int) 1e9 + 7;
        long ans = 1;
        for (int i = 1; i < complexity.length; ++i) {
            if (complexity[i] <= complexity[0]) {
                return 0;
            }
            ans = ans * i % mod;
        }
        return (int) ans;
    }

public String shortestSuperstring(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        if (m > n) {
            return shortestSuperstring(s2, s1);
        }
        if (s2.contains(s1)) {
            return s2;
        }
        for (int i = 0; i < m; i++) {
            if (s2.startsWith(s1.substring(i))) {
                return s1.substring(0, i) + s2;
            }
            if (s2.endsWith(s1.substring(0, m - i))) {
                return s2 + s1.substring(m - i);
            }
        }
        return s1 + s2;
    }

public int minMoves(String[] classroom, int energy) {
       int m = classroom.length, n = classroom[0].length();
       int[][] d = new int[m][n];
       int x = 0, y = 0, cnt = 0;
       for (int i = 0; i < m; i++) {
           String row = classroom[i];
           for (int j = 0; j < n; j++) {
               char c = row.charAt(j);
               if (c == 'S') {
                   x = i;
                   y = j;
               } else if (c == 'L') {
                   d[i][j] = cnt;
                   cnt++;
               }
           }
       }
       if (cnt == 0) {
           return 0;
       }
       boolean[][][][] vis = new boolean[m][n][energy + 1][1 << cnt];
       List<int[]> q = new ArrayList<>();
       q.add(new int[] {x, y, energy, (1 << cnt) - 1});
       vis[x][y][energy][(1 << cnt) - 1] = true;
       int[] dirs = {-1, 0, 1, 0, -1};
       int ans = 0;
       while (!q.isEmpty()) {
           List<int[]> t = q;
           q = new ArrayList<>();
           for (int[] state : t) {
               int i = state[0], j = state[1], curEnergy = state[2], mask = state[3];
               if (mask == 0) {
                   return ans;
               }
               if (curEnergy <= 0) {
                   continue;
               }
               for (int k = 0; k < 4; k++) {
                   int nx = i + dirs[k], ny = j + dirs[k + 1];
                   if (nx >= 0 && nx < m && ny >= 0 && ny < n && classroom[nx].charAt(ny) != 'X') {
                       int nxtEnergy = classroom[nx].charAt(ny) == 'R' ? energy : curEnergy - 1;
                       int nxtMask = mask;
                       if (classroom[nx].charAt(ny) == 'L') {
                           nxtMask &= ~(1 << d[nx][ny]);
                       }
                       if (!vis[nx][ny][nxtEnergy][nxtMask]) {
                           vis[nx][ny][nxtEnergy][nxtMask] = true;
                           q.add(new int[] {nx, ny, nxtEnergy, nxtMask});
                       }
                   }
               }
           }
           ans++;
       }
       return -1;
   }

public String resultingString(String s) {
        StringBuilder stk = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (stk.length() > 0 && isContiguous(stk.charAt(stk.length() - 1), c)) {
                stk.deleteCharAt(stk.length() - 1);
            } else {
                stk.append(c);
            }
        }
        return stk.toString();
    }

    private boolean isContiguous(char a, char b) {
        int t = Math.abs(a - b);
        return t == 1 || t == 25;
    }

public long sumOfLargestPrimes(String s) {
      Set<Long> st = new HashSet<>();
      int n = s.length();

      for (int i = 0; i < n; i++) {
          long x = 0;
          for (int j = i; j < n; j++) {
              x = x * 10 + (s.charAt(j) - '0');
              if (is_prime(x)) {
                  st.add(x);
              }
          }
      }

      List<Long> sorted = new ArrayList<>(st);
      Collections.sort(sorted);

      long ans = 0;
      int start = Math.max(0, sorted.size() - 3);
      for (int idx = start; idx < sorted.size(); idx++) {
          ans += sorted.get(idx);
      }
      return ans;
  }

public class Sorter {
    public static void bubbleSort(int[] arr) {
        boolean swapped;
        do {
            swapped = false;
            for (int i = 1; i < arr.length; i++) {
                if (arr[i-1] > arr[i]) {
                    int temp = arr[i];
                    arr[i] = arr[i-1];
                    arr[i-1] = temp;
                    swapped = true;
                }
            }
        } while (swapped);
    }
}

public class StatsUtil {
    public static double stddev(double[] nums) {
        double mean = 0;
        for (double n : nums) mean += n;
        mean /= nums.length;

        double sumSq = 0;
        for (double n : nums) sumSq += (n - mean) * (n - mean);

        return Math.sqrt(sumSq / nums.length);
    }
}

public class MatrixUtil {
    public static int[][] scalarMultiply(int[][] matrix, int scalar) {
        int[][] result = new int[matrix.length][matrix[0].length];
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                result[i][j] = matrix[i][j] * scalar;
            }
        }
        return result;
    }
}

public class Factorial {
    public static long calc(int n) {
        if (n <= 1) return 1;
