public static ArchiveResult archiveOldFiles(Path directory, Duration maxAge, 
                                              long maxSizeBytes) throws IOException {

        Instant cutoffTime = Instant.now().minus(maxAge);
        AtomicLong totalArchivedSize = new AtomicLong(0);
        AtomicLong archivedCount = new AtomicLong(0);
        List<String> errors = new ArrayList<>();

        // Create archive directory
        Path archiveDir = directory.resolve("archive");
        Files.createDirectories(archiveDir);

        try (DirectoryStream<Path> stream = Files.newDirectoryStream(directory)) {
            for (Path file : stream) {
                if (Files.isRegularFile(file)) {
                    try {
                        BasicFileAttributes attrs = Files.readAttributes(file, BasicFileAttributes.class);

                        // Check if file meets archival criteria
                        boolean tooOld = attrs.lastModifiedTime().toInstant().isBefore(cutoffTime);
                        boolean tooLarge = attrs.size() > maxSizeBytes;

                        if (tooOld || tooLarge) {
                            Path archiveFile = archiveDir.resolve(file.getFileName());

                            // Handle duplicate names
                            int counter = 1;
                            while (Files.exists(archiveFile)) {
                                String fileName = file.getFileName().toString();
                                String baseName = fileName.substring(0, fileName.lastIndexOf('.'));
                                String extension = fileName.substring(fileName.lastIndexOf('.'));
                                archiveFile = archiveDir.resolve(baseName + "_" + counter + extension);
                                counter++;
                            }

                            Files.move(file, archiveFile);
                            totalArchivedSize.addAndGet(attrs.size());
                            archivedCount.incrementAndGet();

                            System.out.printf("Archived: %s -> %s (size: %d bytes)%n",
                                            file.getFileName(), archiveFile.getFileName(), attrs.size());
                        }

                    } catch (IOException e) {
                        String error = String.format("Failed to archive %s: %s", file, e.getMessage());
                        errors.add(error);
                        System.err.println(error);
                    }
                }
            }
        }

        return new ArchiveResult(archivedCount.get(), totalArchivedSize.get(), errors);
    }

/**
     * Recursively find files matching criteria
     */
    public static List<Path> findFiles(Path startDir, String glob, long maxDepth) throws IOException {
        PathMatcher matcher = FileSystems.getDefault().getPathMatcher("glob:" + glob);
        List<Path> matchingFiles = new ArrayList<>();

        Files.walkFileTree(startDir, EnumSet.noneOf(FileVisitOption.class), 
                          (int) maxDepth, new SimpleFileVisitor<Path>() {

            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (matcher.matches(file.getFileName())) {
                    matchingFiles.add(file);
                }
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException exc) {
                System.err.printf("Failed to visit file %s: %s%n", file, exc.getMessage());
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                // Skip hidden directories
                if (dir.getFileName().toString().startsWith(".")) {
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return FileVisitResult.CONTINUE;
            }
        });

        return matchingFiles;
    }

/**
     * Inserts element with timeout, returns false if timeout expires
     */
    public boolean offer(T item, long timeout, TimeUnit unit) throws InterruptedException {
        if (item == null) {
            throw new IllegalArgumentException("Cannot insert null item");
        }

        long nanos = unit.toNanos(timeout);
        lock.lock();

        try {
            while (count == capacity) {
                if (nanos <= 0) {
                    rejectedOffers++;
                    return false;
                }
                nanos = notFull.awaitNanos(nanos);
            }

            enqueue(item);
            totalOffered++;
            return true;

        } finally {
            lock.unlock();
        }
    }

/**
     * Check if logging is enabled for specific level
     */
    public boolean isLoggingEnabled(String loggerName, String level) {
        String configuredLevel = getLoggerLevel(loggerName);
        return getLogLevelPriority(level) >= getLogLevelPriority(configuredLevel);
    }

    private void loadDefaultConfiguration() {
        // Default logging levels
        loggerLevels.put("ROOT", "INFO");
        loggerLevels.put("com.company.security", "DEBUG");
        loggerLevels.put("com.company.database", "WARN");
        loggerLevels.put("com.company.performance", "ERROR");
    }

    private void validateConfiguration(Map<String, String> config) {
        if (config == null || config.isEmpty()) {
            throw new IllegalArgumentException("Configuration cannot be null or empty");
        }

        for (Map.Entry<String, String> entry : config.entrySet()) {
            if (entry.getKey() == null || entry.getKey().trim().isEmpty()) {
                throw new IllegalArgumentException("Logger name cannot be null or empty");
            }
            if (entry.getValue() == null || !isValidLogLevel(entry.getValue())) {
                throw new IllegalArgumentException("Invalid log level: " + entry.getValue());
            }
        }
    }

    private boolean isValidLogLevel(String level) {
        return Arrays.asList("TRACE", "DEBUG", "INFO", "WARN", "ERROR", "FATAL")
                     .contains(level.toUpperCase());
    }

    private int getLogLevelPriority(String level) {
        switch (level.toUpperCase()) {
            case "TRACE": return 0;
            case "DEBUG": return 1;
            case "INFO": return 2;
            case "WARN": return 3;
            case "ERROR": return 4;
            case "FATAL": return 5;
            default: return 2; // Default to INFO
        }
    }

public String getLoggerLevel(String loggerName) {
        Lock readLock = configLock.readLock();
        readLock.lock();

        try {
            return loggerLevels.getOrDefault(loggerName, "INFO");
        } finally {
            readLock.unlock();
        }
    }

/**
     * Returns the singleton instance using double-checked locking pattern.
     * This ensures thread safety while maintaining performance.
     */
    public static LoggingConfigManager getInstance() {
        // First check without synchronization for performance
        if (instance == null) {
            synchronized (LoggingConfigManager.class) {
                // Second check within synchronized block
                if (instance == null) {
                    instance = new LoggingConfigManager();
                }
            }
        }
        return instance;
    }

public boolean canJump(int[] nums) {
        int mx = 0;
        for (int i = 0; i < nums.length; ++i) {
            if (mx < i) {
                return false;
            }
            mx = Math.max(mx, i + nums[i]);
        }
        return true;
    }

private boolean dfs(int i, int j, int k) {
        if (k == word.length() - 1) {
            return board[i][j] == word.charAt(k);
        }
        if (board[i][j] != word.charAt(k)) {
            return false;
        }
        char c = board[i][j];
        board[i][j] = '0';
        int[] dirs = {-1, 0, 1, 0, -1};
        for (int u = 0; u < 4; ++u) {
            int x = i + dirs[u], y = j + dirs[u + 1];
            if (x >= 0 && x < m && y >= 0 && y < n && board[x][y] != '0' && dfs(x, y, k + 1)) {
                return true;
            }
        }
        board[i][j] = c;
        return false;
    }

private int m;
    private int n;
    private String word;
    private char[][] board;

    public boolean exist(char[][] board, String word) {
        m = board.length;
        n = board[0].length;
        this.word = word;
        this.board = board;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (dfs(i, j, 0)) {
                    return true;
                }
            }
        }
        return false;
    }

