public async Task<CustomerDto> CreateCustomerAsync(CreateCustomerDto customerDto)
        {
            try
            {
                // Validate input parameters
                if (customerDto == null)
                    throw new ArgumentNullException(nameof(customerDto));

                // Business rule validation
                if (!IsValidEmailAddress(customerDto.EmailAddress))
                    throw new ValidationException("Invalid email address format");

                // Check for duplicate customers
                var existingCustomer = await m_customerRepository.GetByEmailAsync(customerDto.EmailAddress);
                if (existingCustomer != null)
                    throw new BusinessRuleException("Customer with this email already exists");

                // Create customer entity
                var customer = new Customer
                {
                    FirstName = customerDto.FirstName,
                    LastName = customerDto.LastName,
                    EmailAddress = customerDto.EmailAddress,
                    DateCreated = DateTime.UtcNow,
                    IsActive = true
                };

                // Persist to database
                var createdCustomer = await m_customerRepository.CreateAsync(customer);

                // Send welcome email
                await m_emailService.SendWelcomeEmailAsync(createdCustomer.EmailAddress);

                m_logger.LogInformation($"Successfully created customer with ID: {createdCustomer.CustomerId}");

                return MapToDto(createdCustomer);
            }
            catch (Exception ex)
            {
                m_logger.LogError(ex, "Failed to create customer");
                throw;
            }
        }

        private bool IsValidEmailAddress(string emailAddress)
        {
            return !string.IsNullOrWhiteSpace(emailAddress) && 
                   emailAddress.Contains("@") && 
                   emailAddress.Contains(".");
        }

using System.Collections.Immutable;

namespace FinancialCalculators;

public record Transaction(decimal Amount, DateTime Date, string Category, string Description);
public record MonthlyReport(DateTime Month, decimal TotalIncome, decimal TotalExpenses, decimal NetFlow, 
                           ImmutableList<CategorySummary> Categories);
public record CategorySummary(string Category, decimal Amount, int TransactionCount);

public static class FinancialAnalyzer
{
    public static MonthlyReport GenerateMonthlyReport(IEnumerable<Transaction> transactions, DateTime month) =>
        transactions
            .Where(t => t.Date.Year == month.Year && t.Date.Month == month.Month)
            .Aggregate(
                seed: new { Income = 0m, Expenses = 0m, Categories = new Dictionary<string, List<Transaction>>() },
                func: (acc, transaction) => transaction.Amount >= 0 
                    ? acc with { Income = acc.Income + transaction.Amount, Categories = AddToCategory(acc.Categories, transaction) }
                    : acc with { Expenses = acc.Expenses + Math.Abs(transaction.Amount), Categories = AddToCategory(acc.Categories, transaction) },
                resultSelector: acc => new MonthlyReport(
                    month,
                    acc.Income,
                    acc.Expenses,
                    acc.Income - acc.Expenses,
                    acc.Categories.Select(kvp => new CategorySummary(
                        kvp.Key,
                        kvp.Value.Sum(t => t.Amount),
                        kvp.Value.Count
                    )).ToImmutableList()
                )
            );

    public static IEnumerable<Transaction> FilterByCategory(this IEnumerable<Transaction> transactions, string category) =>
        transactions.Where(t => string.Equals(t.Category, category, StringComparison.OrdinalIgnoreCase));

    public static decimal CalculateRunningBalance(this IEnumerable<Transaction> transactions) =>
        transactions.OrderBy(t => t.Date).Sum(t => t.Amount);

    private static Dictionary<string, List<Transaction>> AddToCategory(Dictionary<string, List<Transaction>> categories, Transaction transaction)
    {
        var updated = new Dictionary<string, List<Transaction>>(categories);
        if (!updated.ContainsKey(transaction.Category))
            updated[transaction.Category] = new List<Transaction>();
        updated[transaction.Category].Add(transaction);
        return updated;
    }
}

public class GameObjectManager
{
    private readonly List<GameObject> objs = new();
    private readonly Dictionary<int, GameObject> objLookup = new();
    private readonly Queue<int> freeIds = new();
    private int nextId = 1;

    public GameObject Create(Vector3 pos, string type = "default")
    {
        var id = freeIds.Count > 0 ? freeIds.Dequeue() : nextId++;
        var obj = new GameObject { Id = id, Pos = pos, Type = type, Active = true };

        objs.Add(obj);
        objLookup[id] = obj;
        return obj;
    }

    public void Update(float dt)
    {
        for (int i = objs.Count - 1; i >= 0; i--)
        {
            var obj = objs[i];
            if (!obj.Active)
            {
                Destroy(obj.Id);
                continue;
            }

            // Update physics
            obj.Vel += obj.Accel * dt;
            obj.Pos += obj.Vel * dt;

            // Apply drag
            obj.Vel *= Math.Max(0, 1 - obj.Drag * dt);

            // Check bounds
            if (obj.Pos.Y < -100) obj.Active = false;
        }
    }

    public GameObject? Find(int id) => objLookup.GetValueOrDefault(id);

    public IEnumerable<GameObject> FindInRadius(Vector3 center, float radius)
    {
        var radiusSq = radius * radius;
        return objs.Where(obj => obj.Active && Vector3.DistanceSq(obj.Pos, center) <= radiusSq);
    }

    private void Destroy(int id)
    {
        if (objLookup.TryGetValue(id, out var obj))
        {
            objs.Remove(obj);
            objLookup.Remove(id);
            freeIds.Enqueue(id);
        }
    }
}

public class GameObject
{
    public int Id;
    public Vector3 Pos, Vel, Accel;
    public string Type = "";
    public bool Active = true;
    public float Drag = 0.1f;
    public Dictionary<string, object> Data = new();
}

public class file_processor
{
    public static bool process_csv_file(string file_path, string output_path)
    {
        StreamReader sr = null;
        StreamWriter sw = null;
        try
        {
            sr = new StreamReader(file_path);
            sw = new StreamWriter(output_path);

            string line;
            int line_count = 0;
            bool has_header = true;

            while ((line = sr.ReadLine()) != null)
            {
                line_count++;

                if (has_header && line_count == 1)
                {
                    sw.WriteLine("processed_" + line);
                    continue;
                }

                string[] fields = line.Split(',');

                if (fields.Length < 3) continue;

                // clean data
                for (int i = 0; i < fields.Length; i++)
                {
                    fields[i] = fields[i].Trim().Replace("\"", "");
                    if (is_numeric(fields[i]))
                    {
                        double val = Convert.ToDouble(fields[i]);
                        fields[i] = val.ToString("F2");
                    }
                }

                // validate required fields
                if (string.IsNullOrEmpty(fields[0]) || string.IsNullOrEmpty(fields[1]))
                    continue;

                string processed_line = string.Join(",", fields) + "," + DateTime.Now.ToString("yyyy-MM-dd");
                sw.WriteLine(processed_line);
            }

            return true;
        }
        catch
        {
            return false;
        }
        finally
        {
            if (sr != null) sr.Close();
            if (sw != null) sw.Close();
        }
    }

    private static bool is_numeric(string str)
    {
        return double.TryParse(str, out _);
    }
}

[ApiController]
[Route("api/[controller]")]
public class ProductsController : ControllerBase
{
    private readonly IProductService _productService;
    private readonly IMemoryCache _cache;
    private readonly ILogger<ProductsController> _logger;

    public ProductsController(IProductService productService, IMemoryCache cache, ILogger<ProductsController> logger)
    {
        _productService = productService;
        _cache = cache;
        _logger = logger;
    }

    [HttpGet]
    public async Task<ActionResult<PagedResult<ProductDto>>> GetProducts(
        [FromQuery] int page = 1,
        [FromQuery] int pageSize = 20,
        [FromQuery] string? category = null,
        [FromQuery] decimal? minPrice = null,
        [FromQuery] decimal? maxPrice = null)
    {
        var cacheKey = $"products_{page}_{pageSize}_{category}_{minPrice}_{maxPrice}";

        if (_cache.TryGetValue(cacheKey, out PagedResult<ProductDto>? cachedResult))
            return Ok(cachedResult);

        var filter = new ProductFilter
        {
            Page = page,
            PageSize = Math.Min(pageSize, 100), // Limit max page size
            Category = category,
            MinPrice = minPrice,
            MaxPrice = maxPrice
        };

        var result = await _productService.GetProductsAsync(filter);

        _cache.Set(cacheKey, result, TimeSpan.FromMinutes(5));

        return Ok(result);
    }

    [HttpPost]
    public async Task<ActionResult<ProductDto>> CreateProduct([FromBody] CreateProductRequest request)
    {
        if (!ModelState.IsValid)
            return BadRequest(ModelState);

        try
        {
            var product = await _productService.CreateProductAsync(request);

            // Invalidate cache
            _cache.Remove("products_*");

            _logger.LogInformation("Created product {ProductId} - {ProductName}", product.Id, product.Name);

            return CreatedAtAction(nameof(GetProduct), new { id = product.Id }, product);
        }
        catch (DuplicateProductException ex)
        {
            return Conflict(new { message = ex.Message });
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Failed to create product");
            return StatusCode(500, new { message = "An error occurred while creating the product" });
        }
    }

    [HttpGet("{id:int}")]
    public async Task<ActionResult<ProductDto>> GetProduct(int id)
    {
