public class OrderProcessingService
{
    private readonly IPaymentGateway _paymentGateway;
    private readonly IInventoryService _inventoryService;
    private readonly IEmailService _emailService;
    private readonly ILogger<OrderProcessingService> _logger;

    public OrderProcessingService(
        IPaymentGateway paymentGateway,
        IInventoryService inventoryService,
        IEmailService emailService,
        ILogger<OrderProcessingService> logger)
    {
        _paymentGateway = paymentGateway ?? throw new ArgumentNullException(nameof(paymentGateway));
        _inventoryService = inventoryService ?? throw new ArgumentNullException(nameof(inventoryService));
        _emailService = emailService ?? throw new ArgumentNullException(nameof(emailService));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
    }

    public async Task<OrderResult> ProcessOrderAsync(Order order)
    {
        _logger.LogInformation("Starting order processing for order {OrderId}", order.Id);

        try
        {
            // Check inventory availability
            var inventoryCheck = await _inventoryService.CheckAvailabilityAsync(order.Items);
            if (!inventoryCheck.IsAvailable)
            {
                _logger.LogWarning("Insufficient inventory for order {OrderId}", order.Id);
                return new OrderResult 
                { 
                    Success = false, 
                    ErrorMessage = "Insufficient inventory",
                    OrderId = order.Id 
                };
            }

            // Reserve inventory
            await _inventoryService.ReserveItemsAsync(order.Items);

            // Process payment
            var paymentResult = await _paymentGateway.ProcessPaymentAsync(
                order.PaymentInfo, 
                order.TotalAmount);

            if (!paymentResult.Success)
            {
                // Release reserved inventory on payment failure
                await _inventoryService.ReleaseReservationAsync(order.Items);
                _logger.LogError("Payment failed for order {OrderId}: {ErrorMessage}", 
                    order.Id, paymentResult.ErrorMessage);

                return new OrderResult 
                { 
                    Success = false, 
                    ErrorMessage = paymentResult.ErrorMessage,
                    OrderId = order.Id 
                };
            }

            // Finalize inventory
            await _inventoryService.FinalizeReservationAsync(order.Items);

            // Send confirmation email
            await _emailService.SendOrderConfirmationAsync(order.CustomerEmail, order);

            _logger.LogInformation("Order {OrderId} processed successfully", order.Id);
            return new OrderResult 
            { 
                Success = true, 
                OrderId = order.Id,
                TransactionId = paymentResult.TransactionId 
            };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unexpected error processing order {OrderId}", order.Id);
            return new OrderResult 
            { 
                Success = false, 
                ErrorMessage = "An unexpected error occurred",
                OrderId = order.Id 
            };
        }
    }
}

public async Task<bool> UpdateAsync(Customer customer)
    {
        if (customer == null)
            throw new ArgumentNullException(nameof(customer));

        var existingCustomer = await _context.Customers
            .FirstOrDefaultAsync(c => c.Id == customer.Id && !c.IsDeleted);

        if (existingCustomer == null)
            return false;

        // Update only specific fields to avoid overwriting audit fields
        existingCustomer.FirstName = customer.FirstName;
        existingCustomer.LastName = customer.LastName;
        existingCustomer.Email = customer.Email;
        existingCustomer.PhoneNumber = customer.PhoneNumber;
        existingCustomer.LastModifiedDate = DateTime.UtcNow;

        await _context.SaveChangesAsync();
        return true;
    }

public async Task<IEnumerable<Customer>> GetActiveCustomersAsync(int page, int pageSize)
    {
        /*
         * Retrieve active customers with pagination
         * Only returns customers who have placed orders in the last 12 months
         * and are not marked as deleted
         */
        var cutoffDate = DateTime.UtcNow.AddMonths(-12);

        return await _context.Customers
            .Where(c => !c.IsDeleted && 
                       c.Orders.Any(o => o.CreatedDate >= cutoffDate))
            .OrderBy(c => c.LastName)
            .ThenBy(c => c.FirstName)
            .Skip((page - 1) * pageSize)
            .Take(pageSize)
            .ToListAsync();
    }

    public async Task<Customer> CreateAsync(Customer customer)
    {
        if (customer == null)
            throw new ArgumentNullException(nameof(customer));

        // Check for duplicate email
        var existingCustomer = await _context.Customers
            .FirstOrDefaultAsync(c => c.Email.ToLower() == customer.Email.ToLower() && !c.IsDeleted);

        if (existingCustomer != null)
            throw new InvalidOperationException($"Customer with email {customer.Email} already exists");

        customer.CreatedDate = DateTime.UtcNow;
        customer.LastModifiedDate = DateTime.UtcNow;

        _context.Customers.Add(customer);
        await _context.SaveChangesAsync();

        return customer;
    }

using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class PlayerController : MonoBehaviour
{
    public float moveSpeed = 5f;
    public float jumpForce = 7f;
    private Rigidbody rb;
    private bool isGrounded;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
    }

    void Update()
    {
        MovePlayer();

        if (Input.GetButtonDown("Jump") && isGrounded)
        {
            Jump();
        }
    }

    private void MovePlayer()
    {
        float moveX = Input.GetAxis("Horizontal");
        float moveZ = Input.GetAxis("Vertical");

        Vector3 movement = new Vector3(moveX, 0, moveZ) * moveSpeed;
        Vector3 newVelocity = new Vector3(movement.x, rb.velocity.y, movement.z);
        rb.velocity = newVelocity;
    }

    private void Jump()
    {
        rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
        isGrounded = false;
    }

    private void OnCollisionEnter(Collision collision)
    {
        if (collision.gameObject.CompareTag("Ground"))
            isGrounded = true;
    }
}

