private decimal _principal;
   private decimal _annualRate;
   private int _termInMonths;
   private PaymentFrequency _frequency;

   public enum PaymentFrequency { Monthly = 12, BiWeekly = 26, Weekly = 52 }

   // Fluent builder methods
   public LoanCalculator WithPrincipal(decimal amount)
   {
       if (amount <= 0) throw new ArgumentException("Principal must be positive");
       _principal = amount;
       return this;
   }

   public LoanCalculator WithAnnualRate(decimal rate)
   {
       if (rate < 0 || rate > 100) throw new ArgumentException("Rate must be between 0 and 100");
       _annualRate = rate / 100; // Convert percentage to decimal
       return this;
   }

   public LoanCalculator WithTerm(int months)
   {
       if (months <= 0) throw new ArgumentException("Term must be positive");
       _termInMonths = months;
       return this;
   }

   public LoanCalculator WithFrequency(PaymentFrequency frequency)
   {
       _frequency = frequency;
       return this;
   }

public LoanPaymentSchedule Calculate()
    {
        ValidateInputs();

        var periodicRate = _annualRate / (int)_frequency;
        var totalPayments = (_termInMonths * (int)_frequency) / 12;

        // Standard loan payment formula: PMT = P * [r(1+r)^n] / [(1+r)^n - 1]
        var paymentAmount = periodicRate == 0 
            ? _principal / totalPayments  // Handle 0% interest
            : _principal * (periodicRate * Math.Pow(1 + (double)periodicRate, totalPayments)) 
              / (Math.Pow(1 + (double)periodicRate, totalPayments) - 1);

        return new LoanPaymentSchedule
        {
            PaymentAmount = Math.Round((decimal)paymentAmount, 2),
            TotalPayments = totalPayments,
            TotalInterest = Math.Round((decimal)paymentAmount * totalPayments - _principal, 2),
            PaymentFrequency = _frequency,
            AmortizationSchedule = GenerateAmortizationSchedule(periodicRate, (decimal)paymentAmount, totalPayments)
        };
    }

    private void ValidateInputs()
    {
        if (_principal == 0) throw new InvalidOperationException("Principal amount not set");
        if (_termInMonths == 0) throw new InvalidOperationException("Loan term not set");
        // Annual rate can be 0 for interest-free loans
    }

var schedule = new List<PaymentDetail>();
        var remainingBalance = _principal;

        for (int i = 1; i <= totalPayments; i++)
        {
            var interestPayment = remainingBalance * periodicRate;
            var principalPayment = paymentAmount - interestPayment;
            remainingBalance -= principalPayment;

            schedule.Add(new PaymentDetail
            {
                PaymentNumber = i,
                PaymentAmount = paymentAmount,
                PrincipalPortion = Math.Round(principalPayment, 2),
                InterestPortion = Math.Round(interestPayment, 2),
                RemainingBalance = Math.Round(Math.Max(0, remainingBalance), 2)
            });
        }

