// Helper methods
   private static int GetIsoWeekOfYear(DateTime date)
   {
       var day = (int)date.DayOfWeek;
       return (date.DayOfYear - day + 10) / 7;
   }

   private static decimal CalculateGrowthRate(IList<SalesRecord> monthData)
   {
       if (monthData.Count < 2) return 0;

       var orderedData = monthData.OrderBy(r => r.SaleDate).ToList();
       var firstHalf = orderedData.Take(orderedData.Count / 2).Sum(r => r.Amount);
       var secondHalf = orderedData.Skip(orderedData.Count / 2).Sum(r => r.Amount);

       return firstHalf == 0 ? 0 : ((secondHalf - firstHalf) / firstHalf) * 100;
   }

public static void BubbleSort(int[] array)
   {
       int n = array.Length;
       bool swapped;

       for (int i = 0; i < n - 1; i++)
       {
           swapped = false;

           // Last i elements are already in place
           for (int j = 0; j < n - i - 1; j++)
           {
               if (array[j] > array[j + 1])
               {
                   // Swap elements
                   int temp = array[j];
                   array[j] = array[j + 1];
                   array[j + 1] = temp;
                   swapped = true;
               }
           }

           // If no swapping occurred, array is sorted
           if (!swapped)
               break;
       }
   }

private double[] _dataset;

    public StatisticalAnalyzer(double[] data)
    {
        _dataset = new double[data.Length];
        Array.Copy(data, _dataset, data.Length);
    }

    public double CalculateMean()
    {
        double sum = 0;

        // Simple iteration to sum all elements
        foreach (double value in _dataset)
        {
            sum += value;
        }

        return sum / _dataset.Length;
    }

    public double CalculateVariance()
    {
        double mean = CalculateMean();
        double sumOfSquares = 0;

        // Calculate sum of squared differences from mean
        for (int i = 0; i < _dataset.Length; i++)
        {
            double difference = _dataset[i] - mean;
            sumOfSquares += difference * difference;
        }

        return sumOfSquares / (_dataset.Length - 1); // Sample variance
    }

public double[] FindOutliers()
   {
       // First sort the array for percentile calculations
       double[] sortedData = new double[_dataset.Length];
       Array.Copy(_dataset, sortedData, _dataset.Length);
       Array.Sort(sortedData);

       // Calculate Q1, Q3, and IQR
       int n = sortedData.Length;
       double q1 = GetPercentile(sortedData, 25);
       double q3 = GetPercentile(sortedData, 75);
       double iqr = q3 - q1;

       double lowerBound = q1 - 1.5 * iqr;
       double upperBound = q3 + 1.5 * iqr;

       // Find outliers
       var outliers = new System.Collections.Generic.List<double>();

       for (int i = 0; i < _dataset.Length; i++)
       {
           if (_dataset[i] < lowerBound || _dataset[i] > upperBound)
           {
               outliers.Add(_dataset[i]);
           }
       }

       return outliers.ToArray();
   }

