public class Solution {
    public int[] TwoSum(int[] nums, int target) {
        Dictionary<int, int> lookup = new Dictionary<int, int>();
        for (var i = 0; i < nums.Length; i++) {
            if (lookup.ContainsKey(target - nums[i])) {
                return new int [] { lookup[target - nums[i]], i };
            }
            lookup[nums[i]] = i;
        }
        return new int[] { };
    }
}

public static int[][] GeneratePascalsTriangle(int numRows)
    {
        int[][] triangle = new int[numRows][];

        for (int i = 0; i < numRows; i++)
        {
            triangle[i] = new int[i + 1];
            triangle[i][0] = 1; // First element of each row is 1
            triangle[i][i] = 1; // Last element of each row is 1

            // Fill middle elements
            for (int j = 1; j < i; j++)
            {
                triangle[i][j] = triangle[i - 1][j - 1] + triangle[i - 1][j];
            }
        }

        return triangle;
    }

int rows = matrix.GetLength(0);
       int cols = matrix.GetLength(1);
       int[] result = new int[rows * cols];
       int index = 0;

       int top = 0, bottom = rows - 1;
       int left = 0, right = cols - 1;

       while (top <= bottom && left <= right)
       {
           // Traverse right across top row
           for (int j = left; j <= right; j++)
           {
               result[index++] = matrix[top, j];
           }
           top++;

           // Traverse down right column
           for (int i = top; i <= bottom; i++)
           {
               result[index++] = matrix[i, right];
           }
           right--;

           // Traverse left across bottom row (if there's still a row)
           if (top <= bottom)
           {
               for (int j = right; j >= left; j--)
               {
                   result[index++] = matrix[bottom, j];
               }
               bottom--;
           }

           // Traverse up left column (if there's still a column)
           if (left <= right)
           {
               for (int i = bottom; i >= top; i--)
               {
                   result[index++] = matrix[i, left];
               }
               left++;
           }
       }

public static int LongestIncreasingSubsequence(int[] array)
    {
        if (array.Length == 0) return 0;

        int[] dp = new int[array.Length];

        // Initialize all elements with length 1
        for (int i = 0; i < array.Length; i++)
        {
            dp[i] = 1;
        }

        // Dynamic programming approach
        for (int i = 1; i < array.Length; i++)
        {
            for (int j = 0; j < i; j++)
            {
                if (array[j] < array[i])
                {
                    dp[i] = Math.Max(dp[i], dp[j] + 1);
                }
            }
        }

        // Find maximum length
        int maxLength = dp[0];
        for (int i = 1; i < dp.Length; i++)
        {
            if (dp[i] > maxLength)
                maxLength = dp[i];
        }

        return maxLength;
    }

public static void FindTripletsSumZero(int[] array)
    {
        Array.Sort(array); // Sort array first
        Console.WriteLine("Triplets that sum to zero:");

        for (int i = 0; i < array.Length - 2; i++)
        {
            // Skip duplicate values for first element
            if (i > 0 && array[i] == array[i - 1])
                continue;

            int left = i + 1;
            int right = array.Length - 1;

            while (left < right)
            {
                int sum = array[i] + array[left] + array[right];

                if (sum == 0)
                {
                    Console.WriteLine($"({array[i]}, {array[left]}, {array[right]})");

                    // Skip duplicates for second element
                    while (left < right && array[left] == array[left + 1])
                        left++;

                    // Skip duplicates for third element
                    while (left < right && array[right] == array[right - 1])
                        right--;

                    left++;
                    right--;
                }
                else if (sum < 0)
                {
                    left++;
                }
                else
                {
                    right--;
                }
            }
        }
    }

public void FindGoldbachPairs(int evenNumber)
   {
       if (evenNumber % 2 != 0 || evenNumber < 4)
       {
           Console.WriteLine("Goldbach conjecture applies only to even numbers >= 4");
           return;
       }

       Console.WriteLine($"Goldbach pairs for {evenNumber}:");
       bool found = false;

       // Check all prime pairs that sum to the even number
       for (int i = 0; i < _primes.Length && _primes[i] <= evenNumber / 2; i++)
       {
           int complement = evenNumber - _primes[i];

           // Binary search for complement in primes array
           if (Array.BinarySearch(_primes, complement) >= 0)
           {
               Console.WriteLine($"{_primes[i]} + {complement} = {evenNumber}");
               found = true;
           }
       }

       if (!found)
       {
           Console.WriteLine("No Goldbach pairs found (this would be a counterexample!)");
       }
   }

if (_primes.Length < 2) return;

       int[] gaps = new int[_primes.Length - 1];
       int maxGap = 0;
       int maxGapIndex = 0;

       // Calculate gaps between consecutive primes
       for (int i = 0; i < _primes.Length - 1; i++)
       {
           gaps[i] = _primes[i + 1] - _primes[i];

           if (gaps[i] > maxGap)
           {
               maxGap = gaps[i];
               maxGapIndex = i;
           }
       }

       Console.WriteLine($"Largest prime gap: {maxGap} between {_primes[maxGapIndex]} and {_primes[maxGapIndex + 1]}");

       // Count frequency of different gap sizes
       var gapFrequency = new System.Collections.Generic.Dictionary<int, int>();

       foreach (int gap in gaps)
       {
           if (gapFrequency.ContainsKey(gap))
               gapFrequency[gap]++;
           else
               gapFrequency[gap] = 1;
       }

       Console.WriteLine("\nGap Size Distribution:");
       foreach (var kvp in gapFrequency)
       {
           Console.WriteLine($"Gap {kvp.Key}: {kvp.Value} occurrences");
       }
