private static Dictionary<string, string> cache = new Dictionary<string, string>();

    public static Dictionary<string, int> CountWordFrequency(string text)
    {
        var wordCount = new Dictionary<string, int>();
        var words = text.ToLower().Split(new char[] { ' ', '.', ',', '!', '?' }, 
                                        StringSplitOptions.RemoveEmptyEntries);

        foreach (var word in words)
        {
            if (wordCount.ContainsKey(word))
                wordCount[word]++;
            else
                wordCount[word] = 1;
        }

        return wordCount;
    }

    // Simple caching mechanism
    public static string ProcessWithCache(string input)
    {
        if (cache.TryGetValue(input, out string cachedResult))
        {
            Console.WriteLine("Cache hit!");
            return cachedResult;
        }

        // Simulate expensive operation
        string result = $"Processed: {input.ToUpper()}";
        cache[input] = result;
        Console.WriteLine("Cache miss - computed and stored");
        return result;
    }

