builder.Services.AddApiVersioning(opt =>
{
    opt.DefaultApiVersion = new ApiVersion(1, 0);
    opt.AssumeDefaultVersionWhenUnspecified = true;
    opt.ApiVersionReader = ApiVersionReader.Combine(
        new UrlSegmentApiVersionReader(),
        new HeaderApiVersionReader("X-Version"));
});

builder.Services.AddVersionedApiExplorer(opt =>
{
    opt.GroupNameFormat = "'v'VVV";
    opt.SubstituteApiVersionInUrl = true;
});

builder.Services.AddMemoryCache();
builder.Services.AddSingleton<IRateLimitService, RateLimitService>();

// Add Swagger
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen();

var app = builder.Build();

// Configure pipeline
if (app.Environment.IsDevelopment())
{
    app.UseSwagger();
    app.UseSwaggerUI(c =>
    {
        c.SwaggerEndpoint("/swagger/v1/swagger.json", "API V1");
        c.SwaggerEndpoint("/swagger/v2/swagger.json", "API V2");
    });
}

app.UseMiddleware<GlobalExceptionMiddleware>();
app.UseMiddleware<RequestLoggingMiddleware>();
app.UseMiddleware<ApiKeyMiddleware>();
app.UseMiddleware<RateLimitMiddleware>();

app.UseRouting();
app.MapControllers();

app.Run();

namespace RestApiDemo.Controllers.V2
{
    [ApiController]
    [ApiVersion("2.0")]
    [Route("api/v{version:apiVersion}/[controller]")]
    [Produces("application/json")]
    public class UsersV2Controller : ControllerBase
    {
        private static List<UserV2> _users = new List<UserV2>
        {
            new UserV2 
            { 
                Id = 1, 
                FirstName = "John", 
                LastName = "Doe", 
                Email = "john@example.com",
                CreatedAt = DateTime.UtcNow.AddDays(-30)
            }
        };

        [HttpGet]
        public ActionResult<ApiResponse<IEnumerable<UserV2>>> GetUsers(
            [FromQuery] int page = 1, 
            [FromQuery] int pageSize = 10)
        {
            var skip = (page - 1) * pageSize;
            var users = _users.Skip(skip).Take(pageSize);
            var totalCount = _users.Count;

            var response = new ApiResponse<IEnumerable<UserV2>>
            {
                Data = users,
                Success = true,
                Message = "Users retrieved successfully",
                Pagination = new PaginationInfo
                {
                    Page = page,
                    PageSize = pageSize,
                    TotalCount = totalCount,
                    TotalPages = (int)Math.Ceiling((double)totalCount / pageSize)
                }
            };

            return Ok(response);
        }

        [HttpGet("{id:int}")]
        public ActionResult<ApiResponse<UserV2>> GetUser(int id)
        {
            var user = _users.FirstOrDefault(u => u.Id == id);

            if (user == null)
            {
                return NotFound(new ApiResponse<UserV2>
                {
                    Success = false,
                    Message = $"User with ID {id} not found"
                });
            }

            return Ok(new ApiResponse<UserV2>
            {
                Data = user,
                Success = true,
                Message = "User retrieved successfully"
            });
        }
    }

public class RateLimitService : IRateLimitService
    {
        private readonly ConcurrentDictionary<string, ClientRequestInfo> _clients = new();

        public Task<bool> IsAllowedAsync(string clientId, int maxRequests = 100, TimeSpan? window = null)
        {
            var windowSize = window ?? TimeSpan.FromMinutes(1);
            var now = DateTime.UtcNow;

            _clients.AddOrUpdate(clientId, 
                new ClientRequestInfo { RequestTimes = new List<DateTime> { now } },
                (key, existing) =>
                {
                    // Remove expired requests
                    existing.RequestTimes.RemoveAll(time => now - time > windowSize);
                    existing.RequestTimes.Add(now);
                    return existing;
                });

            var requestCount = _clients[clientId].RequestTimes.Count;
            return Task.FromResult(requestCount <= maxRequests);
        }

        private class ClientRequestInfo
        {
            public List<DateTime> RequestTimes { get; set; } = new();
        }
    }

private readonly RequestDelegate _next;
        private readonly IRateLimitService _rateLimitService;

        public RateLimitMiddleware(RequestDelegate next, IRateLimitService rateLimitService)
        {
            _next = next;
            _rateLimitService = rateLimitService;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            var clientId = GetClientId(context);
            var isAllowed = await _rateLimitService.IsAllowedAsync(clientId);

            if (!isAllowed)
            {
                context.Response.StatusCode = 429; // Too Many Requests
                await context.Response.WriteAsync("Rate limit exceeded. Please try again later.");
                return;
            }

            await _next(context);
        }

        private string GetClientId(HttpContext context)
        {
            // Use API key if available, otherwise use IP address
            if (context.Request.Headers.TryGetValue("X-API-Key", out var apiKey))
                return apiKey.ToString();

            return context.Connection.RemoteIpAddress?.ToString() ?? "unknown";
        }

[ApiController]
    [Route("api/[controller]")]
    public class ProductsController : ControllerBase
    {
        private static List<Product> _products = new List<Product>
        {
            new Product { Id = 1, Name = "Laptop", Price = 999.99m, Category = "Electronics" },
            new Product { Id = 2, Name = "Book", Price = 19.99m, Category = "Education" }
        };

        // GET: api/products
        [HttpGet]
        public ActionResult<IEnumerable<Product>> GetProducts([FromQuery] string? category = null)
        {
            var products = string.IsNullOrEmpty(category) 
                ? _products 
                : _products.Where(p => p.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

            return Ok(products);
        }

        // GET: api/products/1
        [HttpGet("{id:int}")]
        public ActionResult<Product> GetProduct(int id)
        {
            var product = _products.FirstOrDefault(p => p.Id == id);

            if (product == null)
                return NotFound(new { Message = $"Product with ID {id} not found" });

            return Ok(product);
        }

        // POST: api/products
        [HttpPost]
        public ActionResult<Product> CreateProduct([FromBody] CreateProductRequest request)
        {
            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            var product = new Product
            {
                Id = _products.Max(p => p.Id) + 1,
                Name = request.Name,
                Price = request.Price,
                Category = request.Category
            };

            _products.Add(product);

            return CreatedAtAction(nameof(GetProduct), new { id = product.Id }, product);
        }

        // PUT: api/products/1
        [HttpPut("{id:int}")]
        public IActionResult UpdateProduct(int id, [FromBody] UpdateProductRequest request)
        {
            var product = _products.FirstOrDefault(p => p.Id == id);

            if (product == null)
                return NotFound();

            if (!ModelState.IsValid)
                return BadRequest(ModelState);

            product.Name = request.Name;
            product.Price = request.Price;
            product.Category = request.Category;

            return NoContent();
        }

        // DELETE: api/products/1
        [HttpDelete("{id:int}")]
        public IActionResult DeleteProduct(int id)
        {
            var product = _products.FirstOrDefault(p => p.Id == id);

            if (product == null)
                return NotFound();

            _products.Remove(product);
            return NoContent();
        }
    }

