public class StringInterpolation
{
    public static void Demo()
    {
        string name = "Alice";
        int age = 30;
        decimal salary = 75000.50m;

        // String interpolation with formatting
        string basic = $"Name: {name}, Age: {age}";
        string formatted = $"Salary: {salary:C}, Next year: {age + 1}";

        // Raw string literals (C# 11) - no escaping needed
        string json = """
        {
            "name": "{name}",
            "age": {age},
            "salary": {salary}
        }
        """;

        Console.WriteLine(basic);
        Console.WriteLine(formatted);
        Console.WriteLine(json);
    }
}

public class PatternMatching
{
    public static string AnalyzeValue(object value) => value switch
    {
        string s when s.Length > 10 => $"Long string: {s[..10]}...",
        string s => $"Short string: {s}",
        int n when n > 0 => $"Positive number: {n}",
        int n when n < 0 => $"Negative number: {Math.Abs(n)}",
        int => "Zero",
        double d => $"Decimal: {d:F2}",
        bool b => b ? "True value" : "False value",
        null => "Null value",
        _ => $"Unknown type: {value.GetType().Name}"
    };

    public static void Demo()
    {
        var values = new object[] { "Hello World!", "Hi", 42, -15, 0, 3.14, true, null };

        foreach (var value in values)
        {
            Console.WriteLine(AnalyzeValue(value));
        }
    }
}

using System.Linq;

public class LinqStringProcessing
{
    public static void Demo()
    {
        string text = "The Quick Brown Fox Jumps Over The Lazy Dog";

        // Complex string processing with LINQ
        var result = text
            .Split(' ')
            .Where(word => word.Length > 3)
            .Select(word => word.ToLower())
            .GroupBy(word => word.Length)
            .OrderBy(group => group.Key)
            .Select(group => $"Length {group.Key}: {string.Join(", ", group)}")
            .ToArray();

        Console.WriteLine("Words grouped by length (>3 chars):");
        Array.ForEach(result, Console.WriteLine);

        // Character frequency analysis
        var charFreq = text
            .Where(char.IsLetter)
            .Select(char.ToLower)
            .GroupBy(c => c)
            .OrderByDescending(g => g.Count())
            .Take(5)
            .Select(g => $"{g.Key}: {g.Count()}")
            .ToArray();

        Console.WriteLine("\nTop 5 most frequent letters:");
        Array.ForEach(charFreq, Console.WriteLine);
    }
}

#nullable enable
public class NullableHandling
{
    public static string ProcessName(string? firstName, string? lastName)
    {
        // Null-coalescing assignment (C# 8)
        firstName ??= "Unknown";
        lastName ??= "Person";

        // Null-coalescing with pattern
        return (firstName, lastName) switch
        {
            ("Unknown", "Person") => "Anonymous User",
            var (f, l) when f.Length + l.Length > 20 => $"{f[..10]}... {l[..5]}...",
            var (f, l) => $"{f} {l}"
        };
    }

    public static void Demo()
    {
        var names = new (string?, string?)[]
        {
            ("John", "Doe"),
            (null, "Smith"),
            ("Jane", null),
            (null, null),
            ("VeryLongFirstName", "VeryLongLastName")
        };

        foreach (var (first, last) in names)
        {
            Console.WriteLine($"Input: ({first ?? "null"}, {last ?? "null"}) -> {ProcessName(first, last)}");
        }
    }
}
#nullable restore

public record Calculator(double X, double Y)
{
    // Primary constructor with automatic properties

    // Computed properties
    public double Sum => X + Y;
    public double Product => X * Y;
    public double Difference => X - Y;
    public double Quotient => Y != 0 ? X / Y : double.NaN;

    // Custom methods
    public string GetOperation(string op) => op switch
    {
        "+" => $"{X} + {Y} = {Sum}",
        "-" => $"{X} - {Y} = {Difference}",
        "*" => $"{X} * {Y} = {Product}",
        "/" when Y != 0 => $"{X} / {Y} = {Quotient:F2}",
        "/" => "Division by zero!",
        _ => "Unknown operation"
    };

    // Deconstruction method
    public void Deconstruct(out double sum, out double product)
    {
        sum = Sum;
        product = Product;
    }
}

public class RecordsDemo
{
    public static void Demo()
    {
        var calc = new Calculator(15.5, 4.2);

        // Using record properties
        Console.WriteLine($"Calculator({calc.X}, {calc.Y})");

        // Using custom operations
        string[] operations = { "+", "-", "*", "/", "%" };
        foreach (string op in operations)
        {
            Console.WriteLine(calc.GetOperation(op));
        }

        // Deconstruction
        var (sum, product) = calc;
        Console.WriteLine($"Deconstructed - Sum: {sum}, Product: {product}");

        // Record equality and with expression
        var calc2 = calc with { Y = 0 };
        Console.WriteLine($"Division by zero test: {calc2.GetOperation("/")}");
    }
}

string ProcessText(string input)
