            // Nested local function
            string ReverseWords(string text)
            {
                return string.Join(" ", text.Split(' ').Select(word => 
                    new string(word.Reverse().ToArray())));
            }

            // Main processing logic
            var vowelCount = input.Count(IsVowel);
            var consonantCount = input.Count(c => char.IsLetter(c) && !IsVowel(c));
            var reversed = ReverseWords(input);

            return $"Original: {input}\n" +
                   $"Reversed: {reversed}\n" +
                   $"Vowels: {vowelCount}, Consonants: {consonantCount}";
        }

        string[] texts = { "Hello World", "Programming is Fun", "Local Functions Rock" };

        foreach (string text in texts)
        {
            Console.WriteLine(ProcessText(text));
            Console.WriteLine(new string('-', 40));
        }

