public double A { get; init; } = 1.0;
    public double B { get; init; } = 1.0;

    // Expression-bodied properties
    public double Sum => A + B;
    public double Difference => A - B;
    public double Product => A * B;
    public double Quotient => B != 0 ? A / B : double.NaN;
    public bool IsEqual => Math.Abs(A - B) < 0.0001;

    // Expression-bodied methods
    public string FormatResult(string operation) => operation switch
    {
        "add" => $"{A} + {B} = {Sum:F2}",
        "subtract" => $"{A} - {B} = {Difference:F2}",
        "multiply" => $"{A} × {B} = {Product:F2}",
        "divide" => $"{A} ÷ {B} = {(double.IsNaN(Quotient) ? "undefined" : Quotient.ToString("F2"))}",
        _ => "Unknown operation"
    };

    // Expression-bodied indexer
    public double this[string operation] => operation.ToLower() switch
    {
        "sum" or "add" => Sum,
        "diff" or "subtract" => Difference,
        "product" or "multiply" => Product,
        "quotient" or "divide" => Quotient,
        _ => double.NaN
    };

if (string.IsNullOrWhiteSpace(input))
            return ("", 0, 0, false);

        var processed = input.Trim().ToLower();
        var words = processed.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        var cleanText = new string(processed.Where(char.IsLetterOrDigit).ToArray());
        var isPalindrome = cleanText == new string(cleanText.Reverse().ToArray());

        return (processed, words.Length, input.Length, isPalindrome);
    }

    // Method with named tuple return
    public static (int min, int max, double average, int sum) CalculateStats(params int[] numbers)
    {
        if (numbers.Length == 0)
            return (0, 0, 0, 0);

        return (
            min: numbers.Min(),
            max: numbers.Max(),
            average: numbers.Average(),
            sum: numbers.Sum()
        );

private static readonly HttpClient _httpClient = new HttpClient();

    // Async method with multiple awaits
    public static async Task<string> ProcessUrlContentAsync(string url)
    {
        try
        {
            // Simulate network delay
            await Task.Delay(100);

            // For demo purposes, simulate web content
            string content = $"Sample content from {url} - Lorem ipsum dolor sit amet";

            // Async string processing
            var processedContent = await ProcessContentAsync(content);

            return $"URL: {url}\nProcessed: {processedContent}";
        }
        catch (Exception ex)
        {
            return $"Error processing {url}: {ex.Message}";
        }
    }

    private static async Task<string> ProcessContentAsync(string content)
    {
        // Simulate CPU-intensive work
        await Task.Run(() => Thread.Sleep(50));

        return content
            .Split(' ')
            .Where(word => word.Length > 3)
            .Select(word => word.ToUpper())
            .Aggregate((a, b) => $"{a}-{b}");
    }

    // Parallel async processing
    public static async Task ProcessMultipleUrlsAsync(params string[] urls)
    {
        Console.WriteLine("Starting parallel URL processing...");

        var tasks = urls.Select(ProcessUrlContentAsync).ToArray();
        var results = await Task.WhenAll(tasks);

        for (int i = 0; i < results.Length; i++)
        {
            Console.WriteLine($"Result {i + 1}:");
            Console.WriteLine(results[i]);
            Console.WriteLine(new string('-', 30));
        }
    }

