#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>

struct Employee {
    std::string name;
    int id;
    double salary;
};

std::vector<Employee> parseCSV(const std::string& filename) {
    std::ifstream file(filename);
    std::vector<Employee> employees;
    std::string line;

    while (std::getline(file, line)) {
        std::stringstream ss(line);
        Employee emp;
        std::string token;

        std::getline(ss, emp.name, ',');
        std::getline(ss, token, ',');
        emp.id = std::stoi(token);
        std::getline(ss, token, ',');
        emp.salary = std::stod(token);

        employees.push_back(emp);
    }
    return employees;
}

int main() {
    auto data = parseCSV("employees.csv");
    for (const auto& e : data)
        std::cout << e.name << " - " << e.id << " - $" << e.salary << "\n";
}

