#include <iostream>
#include <fstream>
#include <map>
#include <sstream>

/*
    This class loads a simple key=value configuration file into a map.
    Comments and empty lines are skipped.
*/
class Settings {
    std::map<std::string, std::string> config;
public:
    void load(const std::string& file) {
        std::ifstream in(file);
        std::string line;
        while (std::getline(in, line)) {
            if (line.empty() || line[0] == '#') continue;
            std::istringstream iss(line);
            std::string key, value;
            if (std::getline(iss, key, '=') && std::getline(iss, value))
                config[key] = value;
        }
    }

    std::string get(const std::string& key, const std::string& def = "") const {
        auto it = config.find(key);
        return it != config.end() ? it->second : def;
    }
};

int main() {
    Settings s;
    s.load("settings.cfg");
    std::cout << "Server IP: " << s.get("server_ip", "127.0.0.1") << "\n";
}

#include <iostream>
#include <thread>
#include <vector>
#include <mutex>

std::mutex coutMutex;

void worker(int id) {
    {
        std::lock_guard<std::mutex> lock(coutMutex);
        std::cout << "Worker " << id << " is starting.\n";
    }

    std::this_thread::sleep_for(std::chrono::milliseconds(200));

    {
        std::lock_guard<std::mutex> lock(coutMutex);
        std::cout << "Worker " << id << " is done.\n";
    }
}

int main() {
    std::vector<std::thread> pool;
    for (int i = 0; i < 5; ++i)
        pool.emplace_back(worker, i);

    for (auto& t : pool)
        t.join();
}

#include <iostream>
#include <sstream>

double eval(const std::string& expr) {
    std::stringstream ss(expr);
    double result = 0.0, value = 0.0;
    char op = '+';

    while (ss >> value) {
        if (op == '+') result += value;
        else if (op == '-') result -= value;
        ss >> op;
    }
    return result;
}

int main() {
    std::string input = "10 + 20 - 5 + 3";
    std::cout << "Evaluated: " << eval(input) << "\n";
}

#include <iostream>
#include <vector>

class Grid {
    size_t rows, cols;
    std::vector<std::vector<int>> matrix;
public:
    Grid(size_t r, size_t c) : rows(r), cols(c), matrix(r, std::vector<int>(c)) {}

    void set(size_t r, size_t c, int val) {
        if (r < rows && c < cols)
            matrix[r][c] = val;
    }

    int get(size_t r, size_t c) const {
        return (r < rows && c < cols) ? matrix[r][c] : -1;
    }

    void print() const {
        for (const auto& row : matrix) {
            for (int val : row)
                std::cout << val << " ";
            std::cout << "\n";
        }
    }
};

int main() {
    Grid g(3, 3);
    g.set(1, 1, 5);
    g.print();
}

#include <iostream>
#include <map>

/*
    Basic command-line argument parser.
    Example: ./app --mode=fast --output=log.txt
*/
std::map<std::string, std::string> parseArgs(int argc, char* argv[]) {
    std::map<std::string, std::string> args;
    for (int i = 1; i < argc; ++i) {
        std::string arg = argv[i];
        auto pos = arg.find('=');
        if (arg.rfind("--", 0) == 0 && pos != std::string::npos) {
            std::string key = arg.substr(2, pos - 2);
            std::string value = arg.substr(pos + 1);
            args[key] = value;
        }
    }
    return args;
}

int main(int argc, char* argv[]) {
    auto args = parseArgs(argc, argv);
    std::cout << "Mode: " << args["mode"] << "\n";
    std::cout << "Output: " << args["output"] << "\n";
}

#include <iostream>
#include <functional>
#include <unordered_map>
#include <string>

class EventDispatcher {
    std::unordered_map<std::string, std::function<void()>> handlers;
public:
    void on(const std::string& name, std::function<void()> fn) {
        handlers[name] = std::move(fn);
    }

    void dispatch(const std::string& name) {
        if (handlers.count(name))
            handlers[name]();
    }
};

int main() {
    EventDispatcher ed;
    ed.on("click", []() { std::cout << "Clicked!\n"; });
    ed.on("hover", []() { std::cout << "Hovered!\n"; });

    ed.dispatch("click");
    ed.dispatch("hover");
}

#include <iostream>
#include <stdexcept>
#include <string>
#include <cstring>      // For memset
#include <unistd.h>     // For close()
#include <netdb.h>      // For getaddrinfo()
#include <sys/socket.h> // For socket(), connect()
#include <netinet/in.h>
#include <arpa/inet.h>

class Socket {
    int sockfd;

public:
    Socket() : sockfd(-1) {}

    // Connect to host:port, throws on failure
    void connectTo(const std::string& host, int port) {
        struct sockaddr_in server_addr;
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0)
            throw std::runtime_error("Failed to create socket");

        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(port);

        if (inet_pton(AF_INET, host.c_str(), &server_addr.sin_addr) <= 0)
            throw std::runtime_error("Invalid address: " + host);

        if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0)
            throw std::runtime_error("Connection failed to " + host);
    }

    // Send data over the socket
    void sendAll(const std::string& data) const {
        ssize_t totalSent = 0;
        ssize_t toSend = data.size();
        const char* buf = data.c_str();

        while (totalSent < toSend) {
            ssize_t sent = send(sockfd, buf + totalSent, toSend - totalSent, 0);
            if (sent < 0)
                throw std::runtime_error("Send failed");
            totalSent += sent;
        }
    }

    ~Socket() {
        if (sockfd >= 0) {
            std::cout << "Closing socket...\n";
            close(sockfd);
        }
    }

    // Disable copy
    Socket(const Socket&) = delete;
    Socket& operator=(const Socket&) = delete;

    // Enable move
    Socket(Socket&& other) noexcept : sockfd(other.sockfd) {
        other.sockfd = -1;
    }

    Socket& operator=(Socket&& other) noexcept {
        if (this != &other) {
            if (sockfd >= 0)
                close(sockfd);
            sockfd = other.sockfd;
            other.sockfd = -1;
        }
        return *this;
    }
};

int main() {
    try {
        Socket client;
        client.connectTo("93.184.216.34", 80); // example.com IP address
        client.sendAll("GET / HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n");
        std::cout << "Request sent.\n";
    } catch (const std::exception& e) {
        std::cerr << "Socket error: " << e.what() << "\n";
    }
}

private:
    struct Connection {
        int socket_fd;
        std::chrono::steady_clock::time_point last_used;
        bool is_healthy;

        Connection(int fd) : socket_fd(fd), 
                           last_used(std::chrono::steady_clock::now()),
                           is_healthy(true) {}
    };

std::queue<std::unique_ptr<Connection>> available_connections_;
    mutable std::mutex pool_mutex_;
    std::condition_variable pool_condition_;
    std::size_t max_connections_;
    std::chrono::milliseconds timeout_;

public:
    explicit ConnectionPool(std::size_t max_conn = 50, 
                          std::chrono::milliseconds timeout = std::chrono::milliseconds(5000))
        : max_connections_(max_conn), timeout_(timeout) {}

    /**
     * Acquires a connection from the pool with timeout
     * @return Optional connection pointer, nullopt if timeout exceeded
     */
    [[nodiscard]] std::optional<std::unique_ptr<Connection>> acquire_connection() {
        std::unique_lock<std::mutex> lock(pool_mutex_);

        // Wait for available connection or timeout
        if (!pool_condition_.wait_for(lock, timeout_, 
            [this] { return !available_connections_.empty(); })) {
            return std::nullopt; // Timeout occurred
        }

        auto conn = std::move(available_connections_.front());
        available_connections_.pop();

        // Validate connection health before returning
        if (is_connection_stale(*conn)) {
            conn = create_new_connection();
        }

        return conn;
    }

    void return_connection(std::unique_ptr<Connection> conn) noexcept {
        if (!conn || !conn->is_healthy) return;

        conn->last_used = std::chrono::steady_clock::now();

        {
            std::lock_guard<std::mutex> lock(pool_mutex_);
            available_connections_.push(std::move(conn));
        }
        pool_condition_.notify_one();
    }

private:
    bool is_connection_stale(const Connection& conn) const noexcept {
        auto now = std::chrono::steady_clock::now();
        return (now - conn.last_used) > std::chrono::minutes(5);
    }

    std::unique_ptr<Connection> create_new_connection() {
        // Simulate connection creation
        static int next_fd = 100;
        return std::make_unique<Connection>(++next_fd);
    }

#include <string>
#include <unordered_map>
#include <type_traits>
#include <stdexcept>
#include <sstream>

template<typename T>
struct ConfigTraits {
    static_assert(std::is_default_constructible_v<T>, "Type must be default constructible");

    static T from_string(const std::string& str) {
        if constexpr (std::is_same_v<T, std::string>) {
            return str;
        } else if constexpr (std::is_arithmetic_v<T>) {
            std::istringstream iss(str);
            T value;
            if (!(iss >> value)) {
                throw std::invalid_argument("Cannot convert '" + str + "' to numeric type");
            }
            return value;
        } else if constexpr (std::is_same_v<T, bool>) {
            std::string lower_str = str;
            std::transform(lower_str.begin(), lower_str.end(), lower_str.begin(), ::tolower);
            return (lower_str == "true" || lower_str == "1" || lower_str == "yes");
        } else {
            static_assert(std::is_same_v<T, void>, "Unsupported type for configuration");
        }
    }
};

// Usage example:
void configure_application() {
    ConfigurationManager config;

    config.with("server.port", 8080)
          .with("database.timeout", 30.5)
          .with("logging.enabled", true)
          .with("app.name", std::string("MyApplication"));

    auto port = config.get<int>("server.port", 3000);     // Returns 8080
    auto timeout = config.get<double>("database.timeout"); // Returns 30.5
    auto debug = config.get<bool>("debug.mode", false);    // Returns false (default)
}

class ConfigurationManager {
public:
    /*
     * Generic configuration getter with type safety and default values
     * Uses SFINAE to ensure compile-time type checking
     */
    template<typename T>
    T get(const std::string& key, const T& default_value = T{}) const {
        auto it = config_data_.find(key);
        if (it == config_data_.end()) {
            return default_value;
        }

        try {
            return ConfigTraits<T>::from_string(it->second);
        } catch (const std::exception& e) {
            // Log error in production
            return default_value;
        }
    }

    // Specialized setter that accepts any convertible type
    template<typename T>
    void set(const std::string& key, const T& value) {
        if constexpr (std::is_same_v<T, std::string>) {
            config_data_[key] = value;
        } else {
            std::ostringstream oss;
            oss << value;
            config_data_[key] = oss.str();
        }
    }

    // Fluent interface for chaining configuration calls
    template<typename T>
    ConfigurationManager& with(const std::string& key, const T& value) {
        set(key, value);
        return *this;
    }

private:
    std::unordered_map<std::string, std::string> config_data_;
};

// Old-school enum with scoped enhancement
enum class LogLevel : int {
    DEBUG = 0,
    INFO = 1, 
    WARNING = 2,
    ERROR = 3,
    CRITICAL = 4
};

public:
    // Constructor with resource acquisition
    explicit Logger(const char* filename = nullptr, LogLevel min_lvl = LogLevel::INFO) 
        : buffer_size(MAX_LOGS), current_index(0), min_level(min_lvl), log_file(nullptr) {

        // Allocate buffer using C-style allocation (legacy requirement)
        log_buffer = static_cast<LogEntry*>(malloc(sizeof(LogEntry) * buffer_size));
        if (!log_buffer) {
            throw std::bad_alloc();
        }

        // Initialize all entries
        for (size_t i = 0; i < buffer_size; ++i) {
            new (&log_buffer[i]) LogEntry();  // Placement new for initialization
        }

        if (filename) {
            log_file = fopen(filename, "a");
            // Don't throw on file error - continue with memory logging
        }
    }

    // Destructor ensures cleanup
    ~Logger() {
        if (log_file) {
            fclose(log_file);
        }
        if (log_buffer) {
            // Explicit destructor calls for placement new
            for (size_t i = 0; i < buffer_size; ++i) {
                log_buffer[i].~LogEntry();
            }
            free(log_buffer);
        }
    }

 template<typename... Args>
    void log(LogLevel level, const char* format, Args... args) {
        if (level < min_level) return;

        assert(current_index < buffer_size);  // Debug assertion

        LogEntry* entry = &log_buffer[current_index];
        entry->level = level;
        entry->timestamp = time(nullptr);

        // Safe formatted string creation
        int result = snprintf(entry->message, MAX_LOG_SIZE - 1, format, args...);
        if (result < 0 || result >= MAX_LOG_SIZE - 1) {
            strncpy(entry->message, "[LOG MESSAGE TOO LONG]", MAX_LOG_SIZE - 1);
            entry->message[MAX_LOG_SIZE - 1] = '\0';
        }

        // Write to file if available
        if (log_file) {
            fprintf(log_file, "[%s] %s\n", level_to_string(level), entry->message);
            fflush(log_file);
        }

        current_index = (current_index + 1) % buffer_size;  // Circular buffer
    }

    // C++ style access to recent logs
    std::vector<std::string> get_recent_logs(size_t count = 10) const {
        std::vector<std::string> recent;
        recent.reserve(std::min(count, current_index));

        size_t start = current_index > count ? current_index - count : 0;
        for (size_t i = start; i < current_index; ++i) {
            recent.emplace_back(log_buffer[i].message);
        }

        return recent;
    }

private:
    const char* level_to_string(LogLevel level) const noexcept {
        switch (level) {
            case LogLevel::DEBUG:    return "DEBUG";
            case LogLevel::INFO:     return "INFO";
            case LogLevel::WARNING:  return "WARN";
            case LogLevel::ERROR:    return "ERROR";
            case LogLevel::CRITICAL: return "CRIT";
            default:                 return "UNKNOWN";
        }
    }

using ProcessorFunc = std::function<void(const std::string&)>;

    struct ProcessingStats {
        size_t lines_processed = 0;
        size_t lines_skipped = 0;
        size_t errors_encountered = 0;
        std::vector<std::string> error_messages;
    };

private:
    fs::path input_path_;
    fs::path output_path_;
    std::unique_ptr<std::ifstream> input_stream_;
    std::unique_ptr<std::ofstream> output_stream_;
    ProcessingStats stats_;

public:
    FileProcessor(const fs::path& input, const fs::path& output) 
        : input_path_(input), output_path_(output) {


        if (!fs::exists(input_path_)) {
            throw std::runtime_error("Input file does not exist: " + input_path_.string());
        }

        if (!fs::is_regular_file(input_path_)) {
            throw std::runtime_error("Input path is not a regular file: " + input_path_.string());
        }


        auto output_dir = output_path_.parent_path();
        if (!output_dir.empty() && !fs::exists(output_dir)) {
            fs::create_directories(output_dir);
        }
    }

    ~FileProcessor() {
        // RAII cleanup - streams automatically closed by unique_ptr destructors
        try {
            if (output_stream_ && output_stream_->is_open()) {
                output_stream_->flush();
            }
        } catch (...) {
            // Destructor must not throw - log error in production
        }
    }

try {
            initialize_streams();
        } catch (const std::exception& e) {
            throw std::runtime_error("Failed to initialize file streams: " + std::string(e.what()));
        }

        std::string line;
        size_t line_number = 0;

        // Main processing loop with exception handling
        while (std::getline(*input_stream_, line)) {
            ++line_number;

            try {
                // Skip empty lines if requested
                if (skip_empty_lines && line.empty()) {
                    ++stats_.lines_skipped;
                    continue;
                }

                // Process the line
                processor(line);
                ++stats_.lines_processed;

                // Write processed line to output
                *output_stream_ << line << '\n';

                // Periodic flush for large files
                if (line_number % 1000 == 0) {
                    output_stream_->flush();
                }

            } catch (const std::exception& e) {
                ++stats_.errors_encountered;

                std::string error_msg = "Error processing line " + 
                                      std::to_string(line_number) + ": " + 
                                      e.what();
                stats_.error_messages.push_back(error_msg);

                if (!continue_on_error) {
                    throw std::runtime_error(error_msg);
                }
                // Otherwise continue processing
            }
        }

void example_file_processing() {
    try {
        FileProcessor processor("input.txt", "output.txt");

        // Define processing function
        auto line_processor = [](const std::string& line) {
            // Transform line to uppercase, validate format, etc.
            if (line.length() > 1000) {
                throw std::runtime_error("Line too long");
            }
            // Additional processing...
        };

        auto stats = processor.process_file(line_processor, true, true);

        // Report results
        std::cout << "Processing complete:\n"
                  << "  Lines processed: " << stats.lines_processed << "\n"
                  << "  Lines skipped: " << stats.lines_skipped << "\n"
                  << "  Errors: " << stats.errors_encountered << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Processing failed: " << e.what() << std::endl;
    }
}

HighPerformanceRingBuffer() = default;

   // Non-copyable due to atomic members
   HighPerformanceRingBuffer(const HighPerformanceRingBuffer&) = delete;
   HighPerformanceRingBuffer& operator=(const HighPerformanceRingBuffer&) = delete;

   // Move constructible
   HighPerformanceRingBuffer(HighPerformanceRingBuffer&& other) noexcept 
       : buffer_(std::move(other.buffer_)) {
       write_index_.store(other.write_index_.load());
       read_index_.store(other.read_index_.load());
   }

   /**
    * Lock-free push operation
    * Returns false if buffer is full
    */
   [[nodiscard]] bool push(const T& item) noexcept {
       const uint64_t current_write = write_index_.load(std::memory_order_relaxed);
       const uint64_t next_write = current_write + 1;

       // Check if buffer is full (leave one slot empty to distinguish full from empty)
       if (next_write - read_index_.load(std::memory_order_acquire) >= Capacity) {
           return false;  // Buffer full
       }

       // Store item
       buffer_[current_write & INDEX_MASK] = item;

       // Publish the write
       write_index_.store(next_write, std::memory_order_release);
       return true;
   }

   /**
    * Lock-free pop operation
    * Returns false if buffer is empty
    */
   [[nodiscard]] bool pop(T& item) noexcept {
       const uint64_t current_read = read_index_.load(std::memory_order_relaxed);

       // Check if buffer is empty
       if (current_read == write_index_.load(std::memory_order_acquire)) {
           return false;  // Buffer empty
       }

       // Load item
       item = buffer_[current_read & INDEX_MASK];

       // Publish the read
       read_index_.store(current_read + 1, std::memory_order_release);
       return true;
   }

