#include <stdio.h>

void quicksort(int *arr, int low, int high, int (*cmp)(int, int)) {
    if (low >= high) return;
    int pivot = arr[high];
    int i = low;
    for (int j = low; j < high; j++) {
        if (cmp(arr[j], pivot)) {
            int tmp = arr[i];
            arr[i++] = arr[j];
            arr[j] = tmp;
        }
    }
    int tmp = arr[i];
    arr[i] = arr[high];
    arr[high] = tmp;

    quicksort(arr, low, i - 1, cmp);
    quicksort(arr, i + 1, high, cmp);
}

