int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <src> <dest>\n", argv[0]);
        return 1;
    }

    FILE *src = fopen(argv[1], "rb");
    FILE *dest = fopen(argv[2], "wb");

    if (!src || !dest) return 1;

    char buffer[256];
    size_t n;
    while ((n = fread(buffer, 1, sizeof(buffer), src)) > 0) {
        fwrite(buffer, 1, n, dest);
    }

    fclose(src);
    fclose(dest);
    return 0;
}

