    void log_to_file(const char *message) {
        if (log_file) {
            fprintf(log_file, "[LOG] %s\n", message);
        }
    }

    void close_log_file() {
        if (log_file) fclose(log_file);
    }
#else
    #define init_log_file() ((void)0)
    #define log_to_file(msg) ((void)0)
    #define close_log_file() ((void)0)
#endif

int main() {
    init_log_file();

    LOG("Program started");

    srand(time(NULL));
    int x = rand() % 100;
    int y = rand() % 100;

    LOG("Generated values: x=%d, y=%d", x, y);

    int maximum = MAX(x, y);
    printf("The maximum of %d and %d is %d\n", x, y, maximum);

    log_to_file("Max computed successfully");

    LOG("Program finished");
    close_log_file();

    return 0;
}

#include <stdio.h>
#include <stdarg.h>
#include <time.h>

// Simple logging levels
typedef enum { LOG_INFO, LOG_WARN, LOG_ERROR } LogLevel;

// Logging function with timestamp
void log_message(LogLevel level, const char *fmt, ...) {
    const char *level_str[] = { "INFO", "WARN", "ERROR" };
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);

    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("[%s] [%s]: ", timestamp, level_str[level]);

    va_list args;
    va_start(args, fmt);
    vprintf(fmt, args);
    va_end(args);

    printf("\n");
}

