#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} IntArray;

void init_array(IntArray *arr) {
    arr->data = malloc(4 * sizeof(int));
    arr->size = 0;
    arr->capacity = 4;
}

void push_back(IntArray *arr, int value) {
    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        arr->data = realloc(arr->data, arr->capacity * sizeof(int));
    }
    arr->data[arr->size++] = value;
}

void free_array(IntArray *arr) {
    free(arr->data);
}

int main() {
    IntArray arr;
    init_array(&arr);

    for (int i = 0; i < 10; ++i)
        push_back(&arr, i);

    for (size_t i = 0; i < arr.size; ++i)
        printf("%d ", arr.data[i]);

    free_array(&arr);
    return 0;
}

