#include <stdio.h>

#define N 2

void multiply(int a[N][N], int b[N][N], int result[N][N]) {
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            result[i][j] = 0;
            for (int k = 0; k < N; ++k)
                result[i][j] += a[i][k] * b[k][j];
        }
}

int main() {
    int A[N][N] = {{1, 2}, {3, 4}};
    int B[N][N] = {{5, 6}, {7, 8}};
    int R[N][N];

    multiply(A, B, R);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j)
            printf("%d ", R[i][j]);
        printf("\n");
    }

    return 0;
}

