typedef struct memory_block {
    size_t size;                    // Size of this block
    int is_free;                    // 1 if block is available, 0 if allocated
    struct memory_block *next;      // Pointer to next block in linked list
    uint32_t magic;                 // Magic number for corruption detection
} memory_block_t;

typedef struct {
    void *pool_start;               // Beginning of memory pool
    size_t pool_size;               // Total size of pool
    memory_block_t *free_list;      // Head of free blocks list
    size_t allocated_bytes;         // Currently allocated bytes
    size_t peak_usage;              // Peak memory usage tracking
} memory_pool_t;

#define MAGIC_NUMBER 0xDEADBEEF
#define MIN_BLOCK_SIZE 16
#define ALIGNMENT 8

int memory_pool_init(memory_pool_t *pool, size_t size) {
    if (!pool || size < MIN_BLOCK_SIZE) {
        return -1;
    }

    // Allocate the actual memory pool
    pool->pool_start = malloc(size);
    if (!pool->pool_start) {
        return -1;
    }

    pool->pool_size = size;
    pool->allocated_bytes = 0;
    pool->peak_usage = 0;

    // Initialize first free block spanning entire pool
    memory_block_t *initial_block = (memory_block_t*)pool->pool_start;
    initial_block->size = size - sizeof(memory_block_t);
    initial_block->is_free = 1;
    initial_block->next = NULL;
    initial_block->magic = MAGIC_NUMBER;

    pool->free_list = initial_block;
    return 0;
}

