// Fast packet classification using lookup tables
static const char* protocol_names[] = {
    [1] = "ICMP", [6] = "TCP", [17] = "UDP", [41] = "IPv6"
};

int parse_packet(const uint8_t* packet, size_t len, char* output, size_t output_len) {
    if(len < sizeof(ip_header_t)) return -1;

    ip_header_t* ip = (ip_header_t*)packet;

    // Convert network byte order to host byte order
    uint16_t total_length = ntohs(ip->total_len);
    uint32_t src = ntohl(ip->src_ip);
    uint32_t dst = ntohl(ip->dst_ip);

    snprintf(output, output_len,
        "IP: %d.%d.%d.%d -> %d.%d.%d.%d Proto: %s Len: %d",
        (src>>24)&0xFF, (src>>16)&0xFF, (src>>8)&0xFF, src&0xFF,
        (dst>>24)&0xFF, (dst>>16)&0xFF, (dst>>8)&0xFF, dst&0xFF,
        protocol_names[ip->protocol] ? protocol_names[ip->protocol] : "Unknown",
        total_length);

    return 0;
}

static void trim_whitespace(char *str)
{
    char *end;

    // Trim leading space
    while(isspace((unsigned char)*str)) str++;

    if(*str == 0) return; // All spaces

    // Trim trailing space
    end = str + strlen(str) - 1;
    while(end > str && isspace((unsigned char)*end)) end--;

    end[1] = '\0';
}

static int parse_config_line(const char *line, char *key, char *value)
{
    char *equals_pos;
    char line_copy[MAX_LINE_LENGTH];

    strncpy(line_copy, line, sizeof(line_copy) - 1);
    line_copy[sizeof(line_copy) - 1] = '\0';

    trim_whitespace(line_copy);

    // Skip empty lines and comments
    if (line_copy[0] == '\0' || line_copy[0] == '#' || line_copy[0] == ';') {
        return 0;
    }

    equals_pos = strchr(line_copy, '=');
    if (equals_pos == NULL) {
        return -1; // Invalid format
    }

    *equals_pos = '\0'; // Split the string

    strncpy(key, line_copy, MAX_KEY_LENGTH - 1);
    key[MAX_KEY_LENGTH - 1] = '\0';
    trim_whitespace(key);

    strncpy(value, equals_pos + 1, MAX_VALUE_LENGTH - 1);
    value[MAX_VALUE_LENGTH - 1] = '\0';
    trim_whitespace(value);

    return 1;

int load_config_file(struct config_parser *parser, const char *filename)
{
    FILE *file;
    char line[MAX_LINE_LENGTH];
    char key[MAX_KEY_LENGTH], value[MAX_VALUE_LENGTH];
    int line_number = 0;
    int parse_result;

    if (parser == NULL || filename == NULL) {
        return -1;
    }

    parser->entry_count = 0;
    parser->error_message[0] = '\0';

    file = fopen(filename, "r");
    if (file == NULL) {
        snprintf(parser->error_message, sizeof(parser->error_message),
                "Cannot open file '%s': %s", filename, strerror(errno));
        return -1;
    }

    while (fgets(line, sizeof(line), file) != NULL && 
           parser->entry_count < MAX_CONFIG_ENTRIES) {
        line_number++;

        parse_result = parse_config_line(line, key, value);

        if (parse_result == -1) {
            snprintf(parser->error_message, sizeof(parser->error_message),
                    "Parse error at line %d: Invalid format", line_number);
            fclose(file);
            return -1;
        } else if (parse_result == 1) {
            // Valid key=value pair
            strcpy(parser->entries[parser->entry_count].key, key);
            strcpy(parser->entries[parser->entry_count].value, value);
            parser->entry_count++;
        }
        // parse_result == 0 means comment or empty line, just continue
    }

    fclose(file);
    return parser->entry_count;
}

ypedef double (*window_func_t)(int n, int N);

// Windowing functions for signal processing
double hanning_window(int n, int N) {
    return 0.5 * (1.0 - cos(2.0 * M_PI * n / (N - 1)));
}

double hamming_window(int n, int N) {
    return 0.54 - 0.46 * cos(2.0 * M_PI * n / (N - 1));
}

double blackman_window(int n, int N) {
    double a0 = 0.42659, a1 = 0.49656, a2 = 0.076849;
    return a0 - a1 * cos(2.0*M_PI*n/(N-1)) + a2 * cos(4.0*M_PI*n/(N-1));
}

/**
 * Apply windowing function to signal to reduce spectral leakage
 */
void apply_window(signal_t *sig, window_func_t window) {
    if (!sig || !sig->data || !window) return;

    for (size_t i = 0; i < sig->length; i++) {
        sig->data[i] *= window(i, sig->length);
    }
}

int moving_average_filter(const double *input, double *output, 
                         size_t length, int window_size) {
    if (!input || !output || window_size <= 0) return -1;

    double sum = 0.0;
    int half_window = window_size / 2;

    // Initialize sum with first window
    for (int i = 0; i < window_size && i < (int)length; i++) {
        sum += input[i];
    }

    // Calculate moving average
    for (size_t i = 0; i < length; i++) {
        // Add new sample to window
        if (i + half_window < length) {
            sum += input[i + half_window];
        }

        // Remove old sample from window  
        if ((int)i - half_window - 1 >= 0) {
            sum -= input[i - half_window - 1];
        }

        // Calculate current window size (handles boundaries)
        int current_window = window_size;
        if (i < (size_t)half_window) {
            current_window = i + half_window + 1;
        } else if (i + half_window >= length) {
            current_window = length - (i - half_window);
        }

        output[i] = sum / current_window;
    }

    return 0;
}

