void* worker_thread(void *arg) {
    task_queue_t *queue = (task_queue_t*)arg;
    task_t *task;

    while (1) {
        pthread_mutex_lock(&queue->lock);

        // Wait for tasks or shutdown signal
        while (queue->count == 0 && !queue->shutdown) {
            pthread_cond_wait(&queue->not_empty, &queue->lock);
        }

        if (queue->shutdown && queue->count == 0) {
            pthread_mutex_unlock(&queue->lock);
            break;
        }

        // Dequeue task
        task = queue->head;
        queue->head = task->next;
        if (queue->head == NULL) {
            queue->tail = NULL;
        }
        queue->count--;

        pthread_cond_signal(&queue->not_full);
        pthread_mutex_unlock(&queue->lock);

        // Execute task
        if (task && task->function) {
            task->function(task->argument);
        }
        free(task);
    }

    return NULL;
}

int task_queue_push(task_queue_t *queue, void (*func)(void*), 
                   void *arg, int priority) {
    if (!queue || !func) return -1;

    task_t *new_task = malloc(sizeof(task_t));
    if (!new_task) return -1;

    new_task->function = func;
    new_task->argument = arg;
    new_task->priority = priority;
    new_task->next = NULL;
    clock_gettime(CLOCK_MONOTONIC, &new_task->created);

    pthread_mutex_lock(&queue->lock);

    // Wait if queue is full
    while (queue->count >= queue->max_size && !queue->shutdown) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    if (queue->shutdown) {
        pthread_mutex_unlock(&queue->lock);
        free(new_task);
        return -1;
    }

    // Insert task in priority order
    if (queue->head == NULL) {
        queue->head = queue->tail = new_task;
    } else if (new_task->priority > queue->head->priority) {
        new_task->next = queue->head;
        queue->head = new_task;
    } else {
        task_t *current = queue->head;
        while (current->next && current->next->priority >= new_task->priority) {
            current = current->next;
        }
        new_task->next = current->next;
        current->next = new_task;
        if (new_task->next == NULL) {
            queue->tail = new_task;
        }
    }

    queue->count++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);

    return 0;
}

if (pthread_mutex_init(&queue->lock, NULL) != 0) return -1;
   if (pthread_cond_init(&queue->not_empty, NULL) != 0) {
       pthread_mutex_destroy(&queue->lock);
       return -1;
   }
   if (pthread_cond_init(&queue->not_full, NULL) != 0) {
       pthread_mutex_destroy(&queue->lock);
       pthread_cond_destroy(&queue->not_empty);
       return -1;
   }

