gboolean
cmd_process_input(ProfWin* window, char* inp)
{
    log_debug("Input received: %s", inp);
    g_strchomp(inp);

    if (strlen(inp) == 0) {
        return TRUE;
    }

    // handle command if input starts with a '/'
    if (inp[0] == '/') {
        auto_char char* inp_cpy = strdup(inp);
        char* command = strtok(inp_cpy, " ");
        char* question_mark = strchr(command, '?');
        if (question_mark) {
            *question_mark = '\0';
            auto_gchar gchar* fakeinp = g_strdup_printf("/help %s", command + 1);
            if (fakeinp) {
                return _cmd_execute(window, "/help", fakeinp);
            }
        } else {
            return _cmd_execute(window, command, inp);
        }
    }

    // call a default handler if input didn't start with '/'
    return _cmd_execute_default(window, inp);
}

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <stdbool.h>
#include <string.h>

#define MAX_VERTICES 100
#define INFINITY INT_MAX

typedef struct {
    int vertex;
    int distance;
} heap_node_t;

typedef struct {
    heap_node_t nodes[MAX_VERTICES];
    int size;
} min_heap_t;

// Min heap operations for Dijkstra's algorithm
void swap_nodes(heap_node_t *a, heap_node_t *b) {
    heap_node_t temp = *a;
    *a = *b;
    *b = temp;
}

void heapify_up(min_heap_t *heap, int index) {
    int parent = (index - 1) / 2;

    if (index > 0 && heap->nodes[index].distance < heap->nodes[parent].distance) {
        swap_nodes(&heap->nodes[index], &heap->nodes[parent]);
        heapify_up(heap, parent);
    }
}

if (heap->size >= MAX_VERTICES) return;

    heap->nodes[heap->size].vertex = vertex;
    heap->nodes[heap->size].distance = distance;
    heapify_up(heap, heap->size);
    heap->size++;
}

heap_node_t heap_extract_min(min_heap_t *heap) {
    heap_node_t min_node = heap->nodes[0];
    heap->nodes[0] = heap->nodes[heap->size - 1];
    heap->size--;
    heapify_down(heap, 0);
    return min_node;

void dijkstra(int graph[MAX_VERTICES][MAX_VERTICES], int vertices, 
              int source, int distances[], int predecessors[]) {
    bool visited[MAX_VERTICES];
    min_heap_t heap = {0};

    // Initialize distances and visited array
    for (int i = 0; i < vertices; i++) {
        distances[i] = INFINITY;
        predecessors[i] = -1;
        visited[i] = false;
    }

    distances[source] = 0;
    heap_insert(&heap, source, 0);

    while (heap.size > 0) {
        heap_node_t current = heap_extract_min(&heap);
        int u = current.vertex;

        if (visited[u]) continue;
        visited[u] = true;

        // Check all adjacent vertices
        for (int v = 0; v < vertices; v++) {
            if (graph[u][v] != 0 && !visited[v]) {
                int new_distance = distances[u] + graph[u][v];

                if (new_distance < distances[v]) {
                    distances[v] = new_distance;
                    predecessors[v] = u;
                    heap_insert(&heap, v, new_distance);
                }
            }
        }
    }
}

bool is_safe(int board[][MAX_N], int n, int row, int col) {
    int i, j;

    // Check this column on upper rows
    for (i = 0; i < row; i++) {
        if (board[i][col] == 1) {
            return false;
        }
    }

    // Check upper diagonal on left side
    for (i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) {
        if (board[i][j] == 1) {
            return false;
        }
    }

    // Check upper diagonal on right side  
    for (i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) {
        if (board[i][j] == 1) {
            return false;
        }
    }

    return true;
}

