    }

    if (largest != i) {
        int temp = arr[i];
        arr[i] = arr[largest];
        arr[largest] = temp;

        heapify_sort(arr, n, largest);
    }

int lcs_memo(const char *str1, const char *str2, int m, int n) {
    if (!memo_initialized) {
        init_memo(m, n);
    }

    // Base case
    if (m == 0 || n == 0) {
        return 0;
    }

    // Check if already computed
    if (memo[m][n] != -1) {
        return memo[m][n];
    }

    // If characters match
    if (str1[m-1] == str2[n-1]) {
        memo[m][n] = 1 + lcs_memo(str1, str2, m-1, n-1);
    } else {
        // Take maximum of two possibilities
        int option1 = lcs_memo(str1, str2, m, n-1);
        int option2 = lcs_memo(str1, str2, m-1, n);
        memo[m][n] = (option1 > option2) ? option1 : option2;
    }

    return memo[m][n];
}

void update_height(bst_node_t *node) {
    if (node) {
        int left_height = get_height(node->left);
        int right_height = get_height(node->right);
        node->height = 1 + ((left_height > right_height) ? left_height : right_height);
    }
}

// Get balance factor for AVL operations
int get_balance(bst_node_t *node) {
    return node ? get_height(node->left) - get_height(node->right) : 0;
}

// Right rotate for AVL balancing
bst_node_t* rotate_right(bst_node_t *y) {
    bst_node_t *x = y->left;
    bst_node_t *T2 = x->right;

    // Perform rotation
    x->right = y;
    y->left = T2;

    // Update heights
    update_height(y);
    update_height(x);

    return x; // New root
}

