static void cpu_set_flags(cpu_state_t *cpu, uint8_t value) {
    // Clear flags we're about to set
    cpu->status_flags &= ~(FLAG_ZERO | FLAG_NEGATIVE);

    if (value == 0) {
        cpu->status_flags |= FLAG_ZERO;
    }

    if (value & 0x80) {
        cpu->status_flags |= FLAG_NEGATIVE;
    }
}

static void cpu_push_stack(cpu_state_t *cpu, uint8_t value) {
    uint16_t stack_addr = STACK_BASE + cpu->stack_pointer;
    cpu_write_memory(cpu, stack_addr, value);
    cpu->stack_pointer--;
}

static uint8_t cpu_pop_stack(cpu_state_t *cpu) {
    cpu->stack_pointer++;
    uint16_t stack_addr = STACK_BASE + cpu->stack_pointer;
    return cpu_read_memory(cpu, stack_addr);
}

