static void hal_adc_init(void) {
    // Configure ADC for continuous conversion mode
    ADC_CR2 |= (1 << 0);        // ADON: ADC ON
    ADC_CR2 |= (1 << 1);        // CONT: Continuous conversion
    ADC_CR1 |= (1 << 5);        // EOCIE: End of conversion interrupt enable

    // Configure conversion sequence
    ADC_SQR1 &= ~(0xF << 20);   // Clear sequence length
    ADC_SQR1 |= ((SENSOR_COUNT - 1) << 20); // Set sequence length
}

